focus shadow properly\n      box-shadow: $custom-select-focus-box-shadow;\n    }\n\n    &::-ms-value {\n      // For visual consistency with other platforms/browsers,\n      // suppress the default white text on blue background highlight given to\n      // the selected option text when the (still closed) <select> receives focus\n      // in IE and (under certain conditions) Edge.\n      // See https://github.com/twbs/bootstrap/issues/19398.\n      color: $input-color;\n      background-color: $input-bg;\n    }\n  }\n\n  &[multiple],\n  &[size]:not([size=\"1\"]) {\n    height: auto;\n    padding-right: $custom-select-padding-x;\n    background-image: none;\n  }\n\n  &:disabled {\n    color: $custom-select-disabled-color;\n    background-color: $custom-select-disabled-bg;\n  }\n\n  // Hides the default caret in IE11\n  &::-ms-expand {\n    display: none;\n  }\n\n  // Remove outline from select box in FF\n  &:-moz-focusring {\n    color: transparent;\n    text-shadow: 0 0 0 $custom-select-color;\n  }\n}\n\n.custom-select-sm {\n  height: $custom-select-height-sm;\n  padding-top: $custom-select-padding-y-sm;\n  padding-bottom: $custom-select-padding-y-sm;\n  padding-left: $custom-select-padding-x-sm;\n  @include font-size($custom-select-font-size-sm);\n}\n\n.custom-select-lg {\n  height: $custom-select-height-lg;\n  padding-top: $custom-select-padding-y-lg;\n  padding-bottom: $custom-select-padding-y-lg;\n  padding-left: $custom-select-padding-x-lg;\n  @include font-size($custom-select-font-size-lg);\n}\n\n\n// File\n//\n// Custom file input.\n\n.custom-file {\n  position: relative;\n  display: inline-block;\n  width: 100%;\n  height: $custom-file-height;\n  margin-bottom: 0;\n}\n\n.custom-file-input {\n  position: relative;\n  z-index: 2;\n  width: 100%;\n  height: $custom-file-height;\n  margin: 0;\n  overflow: hidden;\n  opacity: 0;\n\n  &:focus ~ .custom-file-label {\n    border-color: $custom-file-focus-border-color;\n    box-shadow: $custom-file-focus-box-shadow;\n  }\n\n  // Use [disabled] and :disabled to work around https://github.com/twbs/bootstrap/issues/28247\n  &[disabled] ~ .custom-file-label,\n  &:disabled ~ .custom-file-label {\n    background-color: $custom-file-disabled-bg;\n  }\n\n  @each $lang, $value in $custom-file-text {\n    &:lang(#{$lang}) ~ .custom-file-label::after {\n      content: $value;\n    }\n  }\n\n  ~ .custom-file-label[data-browse]::after {\n    content: attr(data-browse);\n  }\n}\n\n.custom-file-label {\n  position: absolute;\n  top: 0;\n  right: 0;\n  left: 0;\n  z-index: 1;\n  height: $custom-file-height;\n  padding: $custom-file-padding-y $custom-file-padding-x;\n  overflow: hidden;\n  font-family: $custom-file-font-family;\n  font-weight: $custom-file-font-weight;\n  line-height: $custom-file-line-height;\n  color: $custom-file-color;\n  background-color: $custom-file-bg;\n  border: $custom-file-border-width solid $custom-file-border-color;\n  @include border-radius($custom-file-border-radius);\n  @include box-shadow($custom-file-box-shadow);\n\n  &::after {\n    position: absolute;\n    top: 0;\n    right: 0;\n    bottom: 0;\n    z-index: 3;\n    display: block;\n    height: $custom-file-height-inner;\n    padding: $custom-file-padding-y $custom-file-padding-x;\n    line-height: $custom-file-line-height;\n    color: $custom-file-button-color;\n    content: \"Browse\";\n    @include gradient-bg($custom-file-button-bg);\n    border-left: inherit;\n    @include border-radius(0 $custom-file-border-radius $custom-file-border-radius 0);\n  }\n}\n\n// Range\n//\n// Style range inputs the same across browsers. Vendor-specific rules for pseudo\n// elements cannot be mixed. As such, there are no shared styles for focus or\n// active states on prefixed selectors.\n\n.custom-range {\n  width: 100%;\n  height: add($custom-range-thumb-height, $custom-range-thumb-focus-box-shadow-width * 2);\n  padding: 0; // Need to reset padding\n  background-color: transparent;\n  appearance: none;\n\n  &:focus {\n    outline: 0;\n\n    // Pseudo-elements must be split across multiple rulesets to have an effect.\n    // No box-shadow() mixin for focus accessibility.\n    &::-webkit-slider-thumb { box-shadow: $custom-range-thumb-focus-box-shadow; }\n    &::-moz-range-thumb     { box-shadow: $custom-range-thumb-focus-box-shadow; }\n    &::-ms-thumb            { box-shadow: $custom-range-thumb-focus-box-shadow; }\n  }\n\n  &::-moz-focus-outer {\n    border: 0;\n  }\n\n  &::-webkit-slider-thumb {\n    width: $custom-range-thumb-width;\n    height: $custom-range-thumb-height;\n    margin-top: ($custom-range-track-height - $custom-range-thumb-height) * .5; // Webkit specific\n    @include gradient-bg($custom-range-thumb-bg);\n    border: $custom-range-thumb-border;\n    @include border-radius($custom-range-thumb-border-radius);\n    @include box-shadow($custom-range-thumb-box-shadow);\n    @include transition($custom-forms-transition);\n    appearance: none;\n\n    &:active {\n      @include gradient-bg($custom-range-thumb-active-bg);\n    }\n  }\n\n  &::-webkit-slider-runnable-track {\n    width: $custom-range-track-width;\n    height: $custom-range-track-height;\n    color: transparent; // Why?\n    cursor: $custom-range-track-cursor;\n    background-color: $custom-range-track-bg;\n    border-color: transparent;\n    @include border-radius($custom-range-track-border-radius);\n    @include box-shadow($custom-range-track-box-shadow);\n  }\n\n  &::-moz-range-thumb {\n    width: $custom-range-thumb-width;\n    height: $custom-range-thumb-height;\n    @include gradient-bg($custom-range-thumb-bg);\n    border: $custom-range-thumb-border;\n    @include border-radius($custom-range-thumb-border-radius);\n    @include box-shadow($custom-range-thumb-box-shadow);\n    @include transition($custom-forms-transition);\n    appearance: none;\n\n    &:active {\n      @include gradient-bg($custom-range-thumb-active-bg);\n    }\n  }\n\n  &::-moz-range-track {\n    width: $custom-range-track-width;\n    height: $custom-range-track-height;\n    color: transparent;\n    cursor: $custom-range-track-cursor;\n    background-color: $custom-range-track-bg;\n    border-color: transparent; // Firefox specific?\n    @include border-radius($custom-range-track-border-radius);\n    @include box-shadow($custom-range-track-box-shadow);\n  }\n\n  &::-ms-thumb {\n    width: $custom-range-thumb-width;\n    height: $custom-range-thumb-height;\n    margin-top: 0; // Edge specific\n    margin-right: $custom-range-thumb-focus-box-shadow-width; // Workaround that overflowed box-shadow is hidden.\n    margin-left: $custom-range-thumb-focus-box-shadow-width;  // Workaround that overflowed box-shadow is hidden.\n    @include gradient-bg($custom-range-thumb-bg);\n    border: $custom-range-thumb-border;\n    @include border-radius($custom-range-thumb-border-radius);\n    @include box-shadow($custom-range-thumb-box-shadow);\n    @include transition($custom-forms-transition);\n    appearance: none;\n\n    &:active {\n      @include gradient-bg($custom-range-thumb-active-bg);\n    }\n  }\n\n  &::-ms-track {\n    width: $custom-range-track-width;\n    height: $custom-range-track-height;\n    color: transparent;\n    cursor: $custom-range-track-cursor;\n    background-color: transparent;\n    border-color: transparent;\n    border-width: $custom-range-thumb-height * .5;\n    @include box-shadow($custom-range-track-box-shadow);\n  }\n\n  &::-ms-fill-lower {\n    background-color: $custom-range-track-bg;\n    @include border-radius($custom-range-track-border-radius);\n  }\n\n  &::-ms-fill-upper {\n    margin-right: 15px; // arbitrary?\n    background-color: $custom-range-track-bg;\n    @include border-radius($custom-range-track-border-radius);\n  }\n\n  &:disabled {\n    &::-webkit-slider-thumb {\n      background-color: $custom-range-thumb-disabled-bg;\n    }\n\n    &::-webkit-slider-runnable-track {\n      cursor: default;\n    }\n\n    &::-moz-range-thumb {\n      background-color: $custom-range-thumb-disabled-bg;\n    }\n\n    &::-moz-range-track {\n      cursor: default;\n    }\n\n    &::-ms-thumb {\n      background-color: $custom-range-thumb-disabled-bg;\n    }\n  }\n}\n\n.custom-control-label::before,\n.custom-file-label,\n.custom-select {\n  @include transition($custom-forms-transition);\n}\n","// Base class\n//\n// Kickstart any navigation component with a set of style resets. Works with\n// `<nav>`s, `<ul>`s or `<ol>`s.\n\n.nav {\n  display: flex;\n  flex-wrap: wrap;\n  padding-left: 0;\n  margin-bottom: 0;\n  list-style: none;\n}\n\n.nav-link {\n  display: block;\n  padding: $nav-link-padding-y $nav-link-padding-x;\n  text-decoration: if($link-decoration == none, null, none);\n\n  @include hover-focus() {\n    text-decoration: none;\n  }\n\n  // Disabled state lightens text\n  &.disabled {\n    color: $nav-link-disabled-color;\n    pointer-events: none;\n    cursor: default;\n  }\n}\n\n//\n// Tabs\n//\n\n.nav-tabs {\n  border-bottom: $nav-tabs-border-width solid $nav-tabs-border-color;\n\n  .nav-link {\n    margin-bottom: -$nav-tabs-border-width;\n    border: $nav-tabs-border-width solid transparent;\n    @include border-top-radius($nav-tabs-border-radius);\n\n    @include hover-focus() {\n      border-color: $nav-tabs-link-hover-border-color;\n    }\n\n    &.disabled {\n      color: $nav-link-disabled-color;\n      background-color: transparent;\n      border-color: transparent;\n    }\n  }\n\n  .nav-link.active,\n  .nav-item.show .nav-link {\n    color: $nav-tabs-link-active-color;\n    background-color: $nav-tabs-link-active-bg;\n    border-color: $nav-tabs-link-active-border-color;\n  }\n\n  .dropdown-menu {\n    // Make dropdown border overlap tab border\n    margin-top: -$nav-tabs-border-width;\n    // Remove the top rounded corners here since there is a hard edge above the menu\n    @include border-top-radius(0);\n  }\n}\n\n\n//\n// Pills\n//\n\n.nav-pills {\n  .nav-link {\n    @include border-radius($nav-pills-border-radius);\n  }\n\n  .nav-link.active,\n  .show > .nav-link {\n    color: $nav-pills-link-active-color;\n    background-color: $nav-pills-link-active-bg;\n  }\n}\n\n\n//\n// Justified variants\n//\n\n.nav-fill {\n  > .nav-link,\n  .nav-item {\n    flex: 1 1 auto;\n    text-align: center;\n  }\n}\n\n.nav-justified {\n  > .nav-link,\n  .nav-item {\n    flex-basis: 0;\n    flex-grow: 1;\n    text-align: center;\n  }\n}\n\n\n// Tabbable tabs\n//\n// Hide tabbable panes to start, show them when `.active`\n\n.tab-content {\n  > .tab-pane {\n    display: none;\n  }\n  > .active {\n    display: block;\n  }\n}\n","// Contents\n//\n// Navbar\n// Navbar brand\n// Navbar nav\n// Navbar text\n// Navbar divider\n// Responsive navbar\n// Navbar position\n// Navbar themes\n\n\n// Navbar\n//\n// Provide a static navbar from which we expand to create full-width, fixed, and\n// other navbar variations.\n\n.navbar {\n  position: relative;\n  display: flex;\n  flex-wrap: wrap; // allow us to do the line break for collapsing content\n  align-items: center;\n  justify-content: space-between; // space out brand from logo\n  padding: $navbar-padding-y $navbar-padding-x;\n\n  // Because flex properties aren't inherited, we need to redeclare these first\n  // few properties so that content nested within behave properly.\n  %container-flex-properties {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    justify-content: space-between;\n  }\n\n  .container,\n  .container-fluid {\n    @extend %container-flex-properties;\n  }\n\n  @each $breakpoint, $container-max-width in $container-max-widths {\n    > .container#{breakpoint-infix($breakpoint, $container-max-widths)} {\n      @extend %container-flex-properties;\n    }\n  }\n}\n\n\n// Navbar brand\n//\n// Used for brand, project, or site names.\n\n.navbar-brand {\n  display: inline-block;\n  padding-top: $navbar-brand-padding-y;\n  padding-bottom: $navbar-brand-padding-y;\n  margin-right: $navbar-padding-x;\n  @include font-size($navbar-brand-font-size);\n  line-height: inherit;\n  white-space: nowrap;\n\n  @include hover-focus() {\n    text-decoration: none;\n  }\n}\n\n\n// Navbar nav\n//\n// Custom navbar navigation (doesn't require `.nav`, but does make use of `.nav-link`).\n\n.navbar-nav {\n  display: flex;\n  flex-direction: column; // cannot use `inherit` to get the `.navbar`s value\n  padding-left: 0;\n  margin-bottom: 0;\n  list-style: none;\n\n  .nav-link {\n    padding-right: 0;\n    padding-left: 0;\n  }\n\n  .dropdown-menu {\n    position: static;\n    float: none;\n  }\n}\n\n\n// Navbar text\n//\n//\n\n.navbar-text {\n  display: inline-block;\n  padding-top: $nav-link-padding-y;\n  padding-bottom: $nav-link-padding-y;\n}\n\n\n// Responsive navbar\n//\n// Custom styles for responsive collapsing and toggling of navbar contents.\n// Powered by the collapse Bootstrap JavaScript plugin.\n\n// When collapsed, prevent the toggleable navbar contents from appearing in\n// the default flexbox row orientation. Requires the use of `flex-wrap: wrap`\n// on the `.navbar` parent.\n.navbar-collapse {\n  flex-basis: 100%;\n  flex-grow: 1;\n  // For always expanded or extra full navbars, ensure content aligns itself\n  // properly vertically. Can be easily overridden with flex utilities.\n  align-items: center;\n}\n\n// Button for toggling the navbar when in its collapsed state\n.navbar-toggler {\n  padding: $navbar-toggler-padding-y $navbar-toggler-padding-x;\n  @include font-size($navbar-toggler-font-size);\n  line-height: 1;\n  background-color: transparent; // remove default button style\n  border: $border-width solid transparent; // remove default button style\n  @include border-radius($navbar-toggler-border-radius);\n\n  @include hover-focus() {\n    text-decoration: none;\n  }\n}\n\n// Keep as a separate element so folks can easily override it with another icon\n// or image file as needed.\n.navbar-toggler-icon {\n  display: inline-block;\n  width: 1.5em;\n  height: 1.5em;\n  vertical-align: middle;\n  content: \"\";\n  background: 50% / 100% 100% no-repeat;\n}\n\n.navbar-nav-scroll {\n  max-height: $navbar-nav-scroll-max-height;\n  overflow-y: auto;\n}\n\n// Generate series of `.navbar-expand-*` responsive classes for configuring\n// where your navbar collapses.\n.navbar-expand {\n  @each $breakpoint in map-keys($grid-breakpoints) {\n    $next: breakpoint-next($breakpoint, $grid-breakpoints);\n    $infix: breakpoint-infix($next, $grid-breakpoints);\n\n    &#{$infix} {\n      @include media-breakpoint-down($breakpoint) {\n        %container-navbar-expand-#{$breakpoint} {\n          padding-right: 0;\n          padding-left: 0;\n        }\n\n        > .container,\n        > .container-fluid {\n          @extend %container-navbar-expand-#{$breakpoint};\n        }\n\n        @each $size, $container-max-width in $container-max-widths {\n          > .container#{breakpoint-infix($size, $container-max-widths)} {\n            @extend %container-navbar-expand-#{$breakpoint};\n          }\n        }\n      }\n\n      @include media-breakpoint-up($next) {\n        flex-flow: row nowrap;\n        justify-content: flex-start;\n\n        .navbar-nav {\n          flex-direction: row;\n\n          .dropdown-menu {\n            position: absolute;\n          }\n\n          .nav-link {\n            padding-right: $navbar-nav-link-padding-x;\n            padding-left: $navbar-nav-link-padding-x;\n          }\n        }\n\n        // For nesting containers, have to redeclare for alignment purposes\n        %container-nesting-#{$breakpoint} {\n          flex-wrap: nowrap;\n        }\n\n        > .container,\n        > .container-fluid {\n          @extend %container-nesting-#{$breakpoint};\n        }\n\n        @each $size, $container-max-width in $container-max-widths {\n          > .container#{breakpoint-infix($size, $container-max-widths)} {\n            @extend %container-nesting-#{$breakpoint};\n          }\n        }\n\n        .navbar-nav-scroll {\n          overflow: visible;\n        }\n\n        .navbar-collapse {\n          display: flex !important; // stylelint-disable-line declaration-no-important\n\n          // Changes flex-bases to auto because of an IE10 bug\n          flex-basis: auto;\n        }\n\n        .navbar-toggler {\n          display: none;\n        }\n      }\n    }\n  }\n}\n\n\n// Navbar themes\n//\n// Styles for switching between navbars with light or dark background.\n\n// Dark links against a light background\n.navbar-light {\n  .navbar-brand {\n    color: $navbar-light-brand-color;\n\n    @include hover-focus() {\n      color: $navbar-light-brand-hover-color;\n    }\n  }\n\n  .navbar-nav {\n    .nav-link {\n      color: $navbar-light-color;\n\n      @include hover-focus() {\n        color: $navbar-light-hover-color;\n      }\n\n      &.disabled {\n        color: $navbar-light-disabled-color;\n      }\n    }\n\n    .show > .nav-link,\n    .active > .nav-link,\n    .nav-link.show,\n    .nav-link.active {\n      color: $navbar-light-active-color;\n    }\n  }\n\n  .navbar-toggler {\n    color: $navbar-light-color;\n    border-color: $navbar-light-toggler-border-color;\n  }\n\n  .navbar-toggler-icon {\n    background-image: escape-svg($navbar-light-toggler-icon-bg);\n  }\n\n  .navbar-text {\n    color: $navbar-light-color;\n    a {\n      color: $navbar-light-active-color;\n\n      @include hover-focus() {\n        color: $navbar-light-active-color;\n      }\n    }\n  }\n}\n\n// White links against a dark background\n.navbar-dark {\n  .navbar-brand {\n    color: $navbar-dark-brand-color;\n\n    @include hover-focus() {\n      color: $navbar-dark-brand-hover-color;\n    }\n  }\n\n  .navbar-nav {\n    .nav-link {\n      color: $navbar-dark-color;\n\n      @include hover-focus() {\n        color: $navbar-dark-hover-color;\n      }\n\n      &.disabled {\n        color: $navbar-dark-disabled-color;\n      }\n    }\n\n    .show > .nav-link,\n    .active > .nav-link,\n    .nav-link.show,\n    .nav-link.active {\n      color: $navbar-dark-active-color;\n    }\n  }\n\n  .navbar-toggler {\n    color: $navbar-dark-color;\n    border-color: $navbar-dark-toggler-border-color;\n  }\n\n  .navbar-toggler-icon {\n    background-image: escape-svg($navbar-dark-toggler-icon-bg);\n  }\n\n  .navbar-text {\n    color: $navbar-dark-color;\n    a {\n      color: $navbar-dark-active-color;\n\n      @include hover-focus() {\n        color: $navbar-dark-active-color;\n      }\n    }\n  }\n}\n","//\n// Base styles\n//\n\n.card {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  min-width: 0; // See https://github.com/twbs/bootstrap/pull/22740#issuecomment-305868106\n  height: $card-height;\n  word-wrap: break-word;\n  background-color: $card-bg;\n  background-clip: border-box;\n  border: $card-border-width solid $card-border-color;\n  @include border-radius($card-border-radius);\n\n  > hr {\n    margin-right: 0;\n    margin-left: 0;\n  }\n\n  > .list-group {\n    border-top: inherit;\n    border-bottom: inherit;\n\n    &:first-child {\n      border-top-width: 0;\n      @include border-top-radius($card-inner-border-radius);\n    }\n\n    &:last-child  {\n      border-bottom-width: 0;\n      @include border-bottom-radius($card-inner-border-radius);\n    }\n  }\n\n  // Due to specificity of the above selector (`.card > .list-group`), we must\n  // use a child selector here to prevent double borders.\n  > .card-header + .list-group,\n  > .list-group + .card-footer {\n    border-top: 0;\n  }\n}\n\n.card-body {\n  // Enable `flex-grow: 1` for decks and groups so that card blocks take up\n  // as much space as possible, ensuring footers are aligned to the bottom.\n  flex: 1 1 auto;\n  // Workaround for the image size bug in IE\n  // See: https://github.com/twbs/bootstrap/pull/28855\n  min-height: 1px;\n  padding: $card-spacer-x;\n  color: $card-color;\n}\n\n.card-title {\n  margin-bottom: $card-spacer-y;\n}\n\n.card-subtitle {\n  margin-top: -$card-spacer-y * .5;\n  margin-bottom: 0;\n}\n\n.card-text:last-child {\n  margin-bottom: 0;\n}\n\n.card-link {\n  @include hover() {\n    text-decoration: none;\n  }\n\n  + .card-link {\n    margin-left: $card-spacer-x;\n  }\n}\n\n//\n// Optional textual caps\n//\n\n.card-header {\n  padding: $card-spacer-y $card-spacer-x;\n  margin-bottom: 0; // Removes the default margin-bottom of <hN>\n  color: $card-cap-color;\n  background-color: $card-cap-bg;\n  border-bottom: $card-border-width solid $card-border-color;\n\n  &:first-child {\n    @include border-radius($card-inner-border-radius $card-inner-border-radius 0 0);\n  }\n}\n\n.card-footer {\n  padding: $card-spacer-y $card-spacer-x;\n  color: $card-cap-color;\n  background-color: $card-cap-bg;\n  border-top: $card-border-width solid $card-border-color;\n\n  &:last-child {\n    @include border-radius(0 0 $card-inner-border-radius $card-inner-border-radius);\n  }\n}\n\n\n//\n// Header navs\n//\n\n.card-header-tabs {\n  margin-right: -$card-spacer-x * .5;\n  margin-bottom: -$card-spacer-y;\n  margin-left: -$card-spacer-x * .5;\n  border-bottom: 0;\n}\n\n.card-header-pills {\n  margin-right: -$card-spacer-x * .5;\n  margin-left: -$card-spacer-x * .5;\n}\n\n// Card image\n.card-img-overlay {\n  position: absolute;\n  top: 0;\n  right: 0;\n  bottom: 0;\n  left: 0;\n  padding: $card-img-overlay-padding;\n  @include border-radius($card-inner-border-radius);\n}\n\n.card-img,\n.card-img-top,\n.card-img-bottom {\n  flex-shrink: 0; // For IE: https://github.com/twbs/bootstrap/issues/29396\n  width: 100%; // Required because we use flexbox and this inherently applies align-self: stretch\n}\n\n.card-img,\n.card-img-top {\n  @include border-top-radius($card-inner-border-radius);\n}\n\n.card-img,\n.card-img-bottom {\n  @include border-bottom-radius($card-inner-border-radius);\n}\n\n\n// Card deck\n\n.card-deck {\n  .card {\n    margin-bottom: $card-deck-margin;\n  }\n\n  @include media-breakpoint-up(sm) {\n    display: flex;\n    flex-flow: row wrap;\n    margin-right: -$card-deck-margin;\n    margin-left: -$card-deck-margin;\n\n    .card {\n      // Flexbugs #4: https://github.com/philipwalton/flexbugs#flexbug-4\n      flex: 1 0 0%;\n      margin-right: $card-deck-margin;\n      margin-bottom: 0; // Override the default\n      margin-left: $card-deck-margin;\n    }\n  }\n}\n\n\n//\n// Card groups\n//\n\n.card-group {\n  // The child selector allows nested `.card` within `.card-group`\n  // to display properly.\n  > .card {\n    margin-bottom: $card-group-margin;\n  }\n\n  @include media-breakpoint-up(sm) {\n    display: flex;\n    flex-flow: row wrap;\n    // The child selector allows nested `.card` within `.card-group`\n    // to display properly.\n    > .card {\n      // Flexbugs #4: https://github.com/philipwalton/flexbugs#flexbug-4\n      flex: 1 0 0%;\n      margin-bottom: 0;\n\n      + .card {\n        margin-left: 0;\n        border-left: 0;\n      }\n\n      // Handle rounded corners\n      @if $enable-rounded {\n        &:not(:last-child) {\n          @include border-right-radius(0);\n\n          .card-img-top,\n          .card-header {\n            // stylelint-disable-next-line property-disallowed-list\n            border-top-right-radius: 0;\n          }\n          .card-img-bottom,\n          .card-footer {\n            // stylelint-disable-next-line property-disallowed-list\n            border-bottom-right-radius: 0;\n          }\n        }\n\n        &:not(:first-child) {\n          @include border-left-radius(0);\n\n          .card-img-top,\n          .card-header {\n            // stylelint-disable-next-line property-disallowed-list\n            border-top-left-radius: 0;\n          }\n          .card-img-bottom,\n          .card-footer {\n            // stylelint-disable-next-line property-disallowed-list\n            border-bottom-left-radius: 0;\n          }\n        }\n      }\n    }\n  }\n}\n\n\n//\n// Columns\n//\n\n.card-columns {\n  .card {\n    margin-bottom: $card-columns-margin;\n  }\n\n  @include media-breakpoint-up(sm) {\n    column-count: $card-columns-count;\n    column-gap: $card-columns-gap;\n    orphans: 1;\n    widows: 1;\n\n    .card {\n      display: inline-block; // Don't let them vertically span multiple columns\n      width: 100%; // Don't let their width change\n    }\n  }\n}\n\n\n//\n// Accordion\n//\n\n.accordion {\n  overflow-anchor: none;\n\n  > .card {\n    overflow: hidden;\n\n    &:not(:last-of-type) {\n      border-bottom: 0;\n      @include border-bottom-radius(0);\n    }\n\n    &:not(:first-of-type) {\n      @include border-top-radius(0);\n    }\n\n    > .card-header {\n      @include border-radius(0);\n      margin-bottom: -$card-border-width;\n    }\n  }\n}\n",".breadcrumb {\n  display: flex;\n  flex-wrap: wrap;\n  padding: $breadcrumb-padding-y $breadcrumb-padding-x;\n  margin-bottom: $breadcrumb-margin-bottom;\n  @include font-size($breadcrumb-font-size);\n  list-style: none;\n  background-color: $breadcrumb-bg;\n  @include border-radius($breadcrumb-border-radius);\n}\n\n.breadcrumb-item {\n  // The separator between breadcrumbs (by default, a forward-slash: \"/\")\n  + .breadcrumb-item {\n    padding-left: $breadcrumb-item-padding;\n\n    &::before {\n      float: left; // Suppress inline spacings and underlining of the separator\n      padding-right: $breadcrumb-item-padding;\n      color: $breadcrumb-divider-color;\n      content: escape-svg($breadcrumb-divider);\n    }\n  }\n\n  // IE9-11 hack to properly handle hyperlink underlines for breadcrumbs built\n  // without `<ul>`s. The `::before` pseudo-element generates an element\n  // *within* the .breadcrumb-item and thereby inherits the `text-decoration`.\n  //\n  // To trick IE into suppressing the underline, we give the pseudo-element an\n  // underline and then immediately remove it.\n  + .breadcrumb-item:hover::before {\n    text-decoration: underline;\n  }\n  // stylelint-disable-next-line no-duplicate-selectors\n  + .breadcrumb-item:hover::before {\n    text-decoration: none;\n  }\n\n  &.active {\n    color: $breadcrumb-active-color;\n  }\n}\n",".pagination {\n  display: flex;\n  @include list-unstyled();\n  @include border-radius();\n}\n\n.page-link {\n  position: relative;\n  display: block;\n  padding: $pagination-padding-y $pagination-padding-x;\n  margin-left: -$pagination-border-width;\n  line-height: $pagination-line-height;\n  color: $pagination-color;\n  text-decoration: if($link-decoration == none, null, none);\n  background-color: $pagination-bg;\n  border: $pagination-border-width solid $pagination-border-color;\n\n  &:hover {\n    z-index: 2;\n    color: $pagination-hover-color;\n    text-decoration: none;\n    background-color: $pagination-hover-bg;\n    border-color: $pagination-hover-border-color;\n  }\n\n  &:focus {\n    z-index: 3;\n    outline: $pagination-focus-outline;\n    box-shadow: $pagination-focus-box-shadow;\n  }\n}\n\n.page-item {\n  &:first-child {\n    .page-link {\n      margin-left: 0;\n      @include border-left-radius($border-radius);\n    }\n  }\n  &:last-child {\n    .page-link {\n      @include border-right-radius($border-radius);\n    }\n  }\n\n  &.active .page-link {\n    z-index: 3;\n    color: $pagination-active-color;\n    background-color: $pagination-active-bg;\n    border-color: $pagination-active-border-color;\n  }\n\n  &.disabled .page-link {\n    color: $pagination-disabled-color;\n    pointer-events: none;\n    // Opinionated: remove the \"hand\" cursor set previously for .page-link\n    cursor: auto;\n    background-color: $pagination-disabled-bg;\n    border-color: $pagination-disabled-border-color;\n  }\n}\n\n\n//\n// Sizing\n//\n\n.pagination-lg {\n  @include pagination-size($pagination-padding-y-lg, $pagination-padding-x-lg, $font-size-lg, $line-height-lg, $pagination-border-radius-lg);\n}\n\n.pagination-sm {\n  @include pagination-size($pagination-padding-y-sm, $pagination-padding-x-sm, $font-size-sm, $line-height-sm, $pagination-border-radius-sm);\n}\n","// Pagination\n\n@mixin pagination-size($padding-y, $padding-x, $font-size, $line-height, $border-radius) {\n  .page-link {\n    padding: $padding-y $padding-x;\n    @include font-size($font-size);\n    line-height: $line-height;\n  }\n\n  .page-item {\n    &:first-child {\n      .page-link {\n        @include border-left-radius($border-radius);\n      }\n    }\n    &:last-child {\n      .page-link {\n        @include border-right-radius($border-radius);\n      }\n    }\n  }\n}\n","// Base class\n//\n// Requires one of the contextual, color modifier classes for `color` and\n// `background-color`.\n\n.badge {\n  display: inline-block;\n  padding: $badge-padding-y $badge-padding-x;\n  @include font-size($badge-font-size);\n  font-weight: $badge-font-weight;\n  line-height: 1;\n  text-align: center;\n  white-space: nowrap;\n  vertical-align: baseline;\n  @include border-radius($badge-border-radius);\n  @include transition($badge-transition);\n\n  @at-root a#{&} {\n    @include hover-focus() {\n      text-decoration: none;\n    }\n  }\n\n  // Empty badges collapse automatically\n  &:empty {\n    display: none;\n  }\n}\n\n// Quick fix for badges in buttons\n.btn .badge {\n  position: relative;\n  top: -1px;\n}\n\n// Pill badges\n//\n// Make them extra rounded with a modifier to replace v3's badges.\n\n.badge-pill {\n  padding-right: $badge-pill-padding-x;\n  padding-left: $badge-pill-padding-x;\n  @include border-radius($badge-pill-border-radius);\n}\n\n// Colors\n//\n// Contextual variations (linked badges get darker on :hover).\n\n@each $color, $value in $theme-colors {\n  .badge-#{$color} {\n    @include badge-variant($value);\n  }\n}\n","@mixin badge-variant($bg) {\n  color: color-yiq($bg);\n  background-color: $bg;\n\n  @at-root a#{&} {\n    @include hover-focus() {\n      color: color-yiq($bg);\n      background-color: darken($bg, 10%);\n    }\n\n    &:focus,\n    &.focus {\n      outline: 0;\n      box-shadow: 0 0 0 $badge-focus-width rgba($bg, .5);\n    }\n  }\n}\n",".jumbotron {\n  padding: $jumbotron-padding ($jumbotron-padding * .5);\n  margin-bottom: $jumbotron-padding;\n  color: $jumbotron-color;\n  background-color: $jumbotron-bg;\n  @include border-radius($border-radius-lg);\n\n  @include media-breakpoint-up(sm) {\n    padding: ($jumbotron-padding * 2) $jumbotron-padding;\n  }\n}\n\n.jumbotron-fluid {\n  padding-right: 0;\n  padding-left: 0;\n  @include border-radius(0);\n}\n","//\n// Base styles\n//\n\n.alert {\n  position: relative;\n  padding: $alert-padding-y $alert-padding-x;\n  margin-bottom: $alert-margin-bottom;\n  border: $alert-border-width solid transparent;\n  @include border-radius($alert-border-radius);\n}\n\n// Headings for larger alerts\n.alert-heading {\n  // Specified to prevent conflicts of changing $headings-color\n  color: inherit;\n}\n\n// Provide class for links that match alerts\n.alert-link {\n  font-weight: $alert-link-font-weight;\n}\n\n\n// Dismissible alerts\n//\n// Expand the right padding and account for the close button's positioning.\n\n.alert-dismissible {\n  padding-right: $close-font-size + $alert-padding-x * 2;\n\n  // Adjust close link position\n  .close {\n    position: absolute;\n    top: 0;\n    right: 0;\n    z-index: 2;\n    padding: $alert-padding-y $alert-padding-x;\n    color: inherit;\n  }\n}\n\n\n// Alternate styles\n//\n// Generate contextual modifier classes for colorizing the alert.\n\n@each $color, $value in $theme-colors {\n  .alert-#{$color} {\n    @include alert-variant(theme-color-level($color, $alert-bg-level), theme-color-level($color, $alert-border-level), theme-color-level($color, $alert-color-level));\n  }\n}\n","@mixin alert-variant($background, $border, $color) {\n  color: $color;\n  @include gradient-bg($background);\n  border-color: $border;\n\n  hr {\n    border-top-color: darken($border, 5%);\n  }\n\n  .alert-link {\n    color: darken($color, 10%);\n  }\n}\n","// Disable animation if transitions are disabled\n@if $enable-transitions {\n  @keyframes progress-bar-stripes {\n    from { background-position: $progress-height 0; }\n    to { background-position: 0 0; }\n  }\n}\n\n.progress {\n  display: flex;\n  height: $progress-height;\n  overflow: hidden; // force rounded corners by cropping it\n  line-height: 0;\n  @include font-size($progress-font-size);\n  background-color: $progress-bg;\n  @include border-radius($progress-border-radius);\n  @include box-shadow($progress-box-shadow);\n}\n\n.progress-bar {\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  overflow: hidden;\n  color: $progress-bar-color;\n  text-align: center;\n  white-space: nowrap;\n  background-color: $progress-bar-bg;\n  @include transition($progress-bar-transition);\n}\n\n.progress-bar-striped {\n  @include gradient-striped();\n  background-size: $progress-height $progress-height;\n}\n\n@if $enable-transitions {\n  .progress-bar-animated {\n    animation: $progress-bar-animation-timing progress-bar-stripes;\n\n    @if $enable-prefers-reduced-motion-media-query {\n      @media (prefers-reduced-motion: reduce) {\n        animation: none;\n      }\n    }\n  }\n}\n",".media {\n  display: flex;\n  align-items: flex-start;\n}\n\n.media-body {\n  flex: 1;\n}\n","// Base class\n//\n// Easily usable on <ul>, <ol>, or <div>.\n\n.list-group {\n  display: flex;\n  flex-direction: column;\n\n  // No need to set list-style: none; since .list-group-item is block level\n  padding-left: 0; // reset padding because ul and ol\n  margin-bottom: 0;\n  @include border-radius($list-group-border-radius);\n}\n\n\n// Interactive list items\n//\n// Use anchor or button elements instead of `li`s or `div`s to create interactive\n// list items. Includes an extra `.active` modifier class for selected items.\n\n.list-group-item-action {\n  width: 100%; // For `<button>`s (anchors become 100% by default though)\n  color: $list-group-action-color;\n  text-align: inherit; // For `<button>`s (anchors inherit)\n\n  // Hover state\n  @include hover-focus() {\n    z-index: 1; // Place hover/focus items above their siblings for proper border styling\n    color: $list-group-action-hover-color;\n    text-decoration: none;\n    background-color: $list-group-hover-bg;\n  }\n\n  &:active {\n    color: $list-group-action-active-color;\n    background-color: $list-group-action-active-bg;\n  }\n}\n\n\n// Individual list items\n//\n// Use on `li`s or `div`s within the `.list-group` parent.\n\n.list-group-item {\n  position: relative;\n  display: block;\n  padding: $list-group-item-padding-y $list-group-item-padding-x;\n  color: $list-group-color;\n  text-decoration: if($link-decoration == none, null, none);\n  background-color: $list-group-bg;\n  border: $list-group-border-width solid $list-group-border-color;\n\n  &:first-child {\n    @include border-top-radius(inherit);\n  }\n\n  &:last-child {\n    @include border-bottom-radius(inherit);\n  }\n\n  &.disabled,\n  &:disabled {\n    color: $list-group-disabled-color;\n    pointer-events: none;\n    background-color: $list-group-disabled-bg;\n  }\n\n  // Include both here for `<a>`s and `<button>`s\n  &.active {\n    z-index: 2; // Place active items above their siblings for proper border styling\n    color: $list-group-active-color;\n    background-color: $list-group-active-bg;\n    border-color: $list-group-active-border-color;\n  }\n\n  & + & {\n    border-top-width: 0;\n\n    &.active {\n      margin-top: -$list-group-border-width;\n      border-top-width: $list-group-border-width;\n    }\n  }\n}\n\n\n// Horizontal\n//\n// Change the layout of list group items from vertical (default) to horizontal.\n\n@each $breakpoint in map-keys($grid-breakpoints) {\n  @include media-breakpoint-up($breakpoint) {\n    $infix: breakpoint-infix($breakpoint, $grid-breakpoints);\n\n    .list-group-horizontal#{$infix} {\n      flex-direction: row;\n\n      > .list-group-item {\n        &:first-child {\n          @include border-bottom-left-radius($list-group-border-radius);\n          @include border-top-right-radius(0);\n        }\n\n        &:last-child {\n          @include border-top-right-radius($list-group-border-radius);\n          @include border-bottom-left-radius(0);\n        }\n\n        &.active {\n          margin-top: 0;\n        }\n\n        + .list-group-item {\n          border-top-width: $list-group-border-width;\n          border-left-width: 0;\n\n          &.active {\n            margin-left: -$list-group-border-width;\n            border-left-width: $list-group-border-width;\n          }\n        }\n      }\n    }\n  }\n}\n\n\n// Flush list items\n//\n// Remove borders and border-radius to keep list group items edge-to-edge. Most\n// useful within other components (e.g., cards).\n\n.list-group-flush {\n  @include border-radius(0);\n\n  > .list-group-item {\n    border-width: 0 0 $list-group-border-width;\n\n    &:last-child {\n      border-bottom-width: 0;\n    }\n  }\n}\n\n\n// Contextual variants\n//\n// Add modifier classes to change text and background color on individual items.\n// Organizationally, this must come after the `:hover` states.\n\n@each $color, $value in $theme-colors {\n  @include list-group-item-variant($color, theme-color-level($color, -9), theme-color-level($color, 6));\n}\n","// List Groups\n\n@mixin list-group-item-variant($state, $background, $color) {\n  .list-group-item-#{$state} {\n    color: $color;\n    background-color: $background;\n\n    &.list-group-item-action {\n      @include hover-focus() {\n        color: $color;\n        background-color: darken($background, 5%);\n      }\n\n      &.active {\n        color: $white;\n        background-color: $color;\n        border-color: $color;\n      }\n    }\n  }\n}\n",".close {\n  float: right;\n  @include font-size($close-font-size);\n  font-weight: $close-font-weight;\n  line-height: 1;\n  color: $close-color;\n  text-shadow: $close-text-shadow;\n  opacity: .5;\n\n  // Override <a>'s hover style\n  @include hover() {\n    color: $close-color;\n    text-decoration: none;\n  }\n\n  &:not(:disabled):not(.disabled) {\n    @include hover-focus() {\n      opacity: .75;\n    }\n  }\n}\n\n// Additional properties for button version\n// iOS requires the button element instead of an anchor tag.\n// If you want the anchor version, it requires `href=\"#\"`.\n// See https://developer.mozilla.org/en-US/docs/Web/Events/click#Safari_Mobile\n\n// stylelint-disable-next-line selector-no-qualifying-type\nbutton.close {\n  padding: 0;\n  background-color: transparent;\n  border: 0;\n}\n\n// Future-proof disabling of clicks on `<a>` elements\n\n// stylelint-disable-next-line selector-no-qualifying-type\na.close.disabled {\n  pointer-events: none;\n}\n",".toast {\n  // Prevents from shrinking in IE11, when in a flex container\n  // See https://github.com/twbs/bootstrap/issues/28341\n  flex-basis: $toast-max-width;\n  max-width: $toast-max-width;\n  @include font-size($toast-font-size);\n  color: $toast-color;\n  background-color: $toast-background-color;\n  background-clip: padding-box;\n  border: $toast-border-width solid $toast-border-color;\n  box-shadow: $toast-box-shadow;\n  opacity: 0;\n  @include border-radius($toast-border-radius);\n\n  &:not(:last-child) {\n    margin-bottom: $toast-padding-x;\n  }\n\n  &.showing {\n    opacity: 1;\n  }\n\n  &.show {\n    display: block;\n    opacity: 1;\n  }\n\n  &.hide {\n    display: none;\n  }\n}\n\n.toast-header {\n  display: flex;\n  align-items: center;\n  padding: $toast-padding-y $toast-padding-x;\n  color: $toast-header-color;\n  background-color: $toast-header-background-color;\n  background-clip: padding-box;\n  border-bottom: $toast-border-width solid $toast-header-border-color;\n  @include border-top-radius(subtract($toast-border-radius, $toast-border-width));\n}\n\n.toast-body {\n  padding: $toast-padding-x; // apply to both vertical and horizontal\n}\n","// .modal-open      - body class for killing the scroll\n// .modal           - container to scroll within\n// .modal-dialog    - positioning shell for the actual modal\n// .modal-content   - actual modal w/ bg and corners and stuff\n\n\n.modal-open {\n  // Kill the scroll on the body\n  overflow: hidden;\n\n  .modal {\n    overflow-x: hidden;\n    overflow-y: auto;\n  }\n}\n\n// Container that the modal scrolls within\n.modal {\n  position: fixed;\n  top: 0;\n  left: 0;\n  z-index: $zindex-modal;\n  display: none;\n  width: 100%;\n  height: 100%;\n  overflow: hidden;\n  // Prevent Chrome on Windows from adding a focus outline. For details, see\n  // https://github.com/twbs/bootstrap/pull/10951.\n  outline: 0;\n  // We deliberately don't use `-webkit-overflow-scrolling: touch;` due to a\n  // gnarly iOS Safari bug: https://bugs.webkit.org/show_bug.cgi?id=158342\n  // See also https://github.com/twbs/bootstrap/issues/17695\n}\n\n// Shell div to position the modal with bottom padding\n.modal-dialog {\n  position: relative;\n  width: auto;\n  margin: $modal-dialog-margin;\n  // allow clicks to pass through for custom click handling to close modal\n  pointer-events: none;\n\n  // When fading in the modal, animate it to slide down\n  .modal.fade & {\n    @include transition($modal-transition);\n    transform: $modal-fade-transform;\n  }\n  .modal.show & {\n    transform: $modal-show-transform;\n  }\n\n  // When trying to close, animate focus to scale\n  .modal.modal-static & {\n    transform: $modal-scale-transform;\n  }\n}\n\n.modal-dialog-scrollable {\n  display: flex; // IE10/11\n  max-height: subtract(100%, $modal-dialog-margin * 2);\n\n  .modal-content {\n    max-height: subtract(100vh, $modal-dialog-margin * 2); // IE10/11\n    overflow: hidden;\n  }\n\n  .modal-header,\n  .modal-footer {\n    flex-shrink: 0;\n  }\n\n  .modal-body {\n    overflow-y: auto;\n  }\n}\n\n.modal-dialog-centered {\n  display: flex;\n  align-items: center;\n  min-height: subtract(100%, $modal-dialog-margin * 2);\n\n  // Ensure `modal-dialog-centered` extends the full height of the view (IE10/11)\n  &::before {\n    display: block; // IE10\n    height: subtract(100vh, $modal-dialog-margin * 2);\n    height: min-content; // Reset height to 0 except on IE\n    content: \"\";\n  }\n\n  // Ensure `.modal-body` shows scrollbar (IE10/11)\n  &.modal-dialog-scrollable {\n    flex-direction: column;\n    justify-content: center;\n    height: 100%;\n\n    .modal-content {\n      max-height: none;\n    }\n\n    &::before {\n      content: none;\n    }\n  }\n}\n\n// Actual modal\n.modal-content {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  width: 100%; // Ensure `.modal-content` extends the full width of the parent `.modal-dialog`\n  // counteract the pointer-events: none; in the .modal-dialog\n  color: $modal-content-color;\n  pointer-events: auto;\n  background-color: $modal-content-bg;\n  background-clip: padding-box;\n  border: $modal-content-border-width solid $modal-content-border-color;\n  @include border-radius($modal-content-border-radius);\n  @include box-shadow($modal-content-box-shadow-xs);\n  // Remove focus outline from opened modal\n  outline: 0;\n}\n\n// Modal background\n.modal-backdrop {\n  position: fixed;\n  top: 0;\n  left: 0;\n  z-index: $zindex-modal-backdrop;\n  width: 100vw;\n  height: 100vh;\n  background-color: $modal-backdrop-bg;\n\n  // Fade for backdrop\n  &.fade { opacity: 0; }\n  &.show { opacity: $modal-backdrop-opacity; }\n}\n\n// Modal header\n// Top section of the modal w/ title and dismiss\n.modal-header {\n  display: flex;\n  align-items: flex-start; // so the close btn always stays on the upper right corner\n  justify-content: space-between; // Put modal header elements (title and dismiss) on opposite ends\n  padding: $modal-header-padding;\n  border-bottom: $modal-header-border-width solid $modal-header-border-color;\n  @include border-top-radius($modal-content-inner-border-radius);\n\n  .close {\n    padding: $modal-header-padding;\n    // auto on the left force icon to the right even when there is no .modal-title\n    margin: (-$modal-header-padding-y) (-$modal-header-padding-x) (-$modal-header-padding-y) auto;\n  }\n}\n\n// Title text within header\n.modal-title {\n  margin-bottom: 0;\n  line-height: $modal-title-line-height;\n}\n\n// Modal body\n// Where all modal content resides (sibling of .modal-header and .modal-footer)\n.modal-body {\n  position: relative;\n  // Enable `flex-grow: 1` so that the body take up as much space as possible\n  // when there should be a fixed height on `.modal-dialog`.\n  flex: 1 1 auto;\n  padding: $modal-inner-padding;\n}\n\n// Footer (for actions)\n.modal-footer {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center; // vertically center\n  justify-content: flex-end; // Right align buttons with flex property because text-align doesn't work on flex items\n  padding: $modal-inner-padding - $modal-footer-margin-between * .5;\n  border-top: $modal-footer-border-width solid $modal-footer-border-color;\n  @include border-bottom-radius($modal-content-inner-border-radius);\n\n  // Place margin between footer elements\n  // This solution is far from ideal because of the universal selector usage,\n  // but is needed to fix https://github.com/twbs/bootstrap/issues/24800\n  > * {\n    margin: $modal-footer-margin-between * .5;\n  }\n}\n\n// Measure scrollbar width for padding body during modal show/hide\n.modal-scrollbar-measure {\n  position: absolute;\n  top: -9999px;\n  width: 50px;\n  height: 50px;\n  overflow: scroll;\n}\n\n// Scale up the modal\n@include media-breakpoint-up(sm) {\n  // Automatically set modal's width for larger viewports\n  .modal-dialog {\n    max-width: $modal-md;\n    margin: $modal-dialog-margin-y-sm-up auto;\n  }\n\n  .modal-dialog-scrollable {\n    max-height: subtract(100%, $modal-dialog-margin-y-sm-up * 2);\n\n    .modal-content {\n      max-height: subtract(100vh, $modal-dialog-margin-y-sm-up * 2);\n    }\n  }\n\n  .modal-dialog-centered {\n    min-height: subtract(100%, $modal-dialog-margin-y-sm-up * 2);\n\n    &::before {\n      height: subtract(100vh, $modal-dialog-margin-y-sm-up * 2);\n      height: min-content;\n    }\n  }\n\n  .modal-content {\n    @include box-shadow($modal-content-box-shadow-sm-up);\n  }\n\n  .modal-sm { max-width: $modal-sm; }\n}\n\n@include media-breakpoint-up(lg) {\n  .modal-lg,\n  .modal-xl {\n    max-width: $modal-lg;\n  }\n}\n\n@include media-breakpoint-up(xl) {\n  .modal-xl { max-width: $modal-xl; }\n}\n","// Base class\n.tooltip {\n  position: absolute;\n  z-index: $zindex-tooltip;\n  display: block;\n  margin: $tooltip-margin;\n  // Our parent element can be arbitrary since tooltips are by default inserted as a sibling of their target element.\n  // So reset our font and text properties to avoid inheriting weird values.\n  @include reset-text();\n  @include font-size($tooltip-font-size);\n  // Allow breaking very long words so they don't overflow the tooltip's bounds\n  word-wrap: break-word;\n  opacity: 0;\n\n  &.show { opacity: $tooltip-opacity; }\n\n  .arrow {\n    position: absolute;\n    display: block;\n    width: $tooltip-arrow-width;\n    height: $tooltip-arrow-height;\n\n    &::before {\n      position: absolute;\n      content: \"\";\n      border-color: transparent;\n      border-style: solid;\n    }\n  }\n}\n\n.bs-tooltip-top {\n  padding: $tooltip-arrow-height 0;\n\n  .arrow {\n    bottom: 0;\n\n    &::before {\n      top: 0;\n      border-width: $tooltip-arrow-height ($tooltip-arrow-width * .5) 0;\n      border-top-color: $tooltip-arrow-color;\n    }\n  }\n}\n\n.bs-tooltip-right {\n  padding: 0 $tooltip-arrow-height;\n\n  .arrow {\n    left: 0;\n    width: $tooltip-arrow-height;\n    height: $tooltip-arrow-width;\n\n    &::before {\n      right: 0;\n      border-width: ($tooltip-arrow-width * .5) $tooltip-arrow-height ($tooltip-arrow-width * .5) 0;\n      border-right-color: $tooltip-arrow-color;\n    }\n  }\n}\n\n.bs-tooltip-bottom {\n  padding: $tooltip-arrow-height 0;\n\n  .arrow {\n    top: 0;\n\n    &::before {\n      bottom: 0;\n      border-width: 0 ($tooltip-arrow-width * .5) $tooltip-arrow-height;\n      border-bottom-color: $tooltip-arrow-color;\n    }\n  }\n}\n\n.bs-tooltip-left {\n  padding: 0 $tooltip-arrow-height;\n\n  .arrow {\n    right: 0;\n    width: $tooltip-arrow-height;\n    height: $tooltip-arrow-width;\n\n    &::before {\n      left: 0;\n      border-width: ($tooltip-arrow-width * .5) 0 ($tooltip-arrow-width * .5) $tooltip-arrow-height;\n      border-left-color: $tooltip-arrow-color;\n    }\n  }\n}\n\n.bs-tooltip-auto {\n  &[x-placement^=\"top\"] {\n    @extend .bs-tooltip-top;\n  }\n  &[x-placement^=\"right\"] {\n    @extend .bs-tooltip-right;\n  }\n  &[x-placement^=\"bottom\"] {\n    @extend .bs-tooltip-bottom;\n  }\n  &[x-placement^=\"left\"] {\n    @extend .bs-tooltip-left;\n  }\n}\n\n// Wrapper for the tooltip content\n.tooltip-inner {\n  max-width: $tooltip-max-width;\n  padding: $tooltip-padding-y $tooltip-padding-x;\n  color: $tooltip-color;\n  text-align: center;\n  background-color: $tooltip-bg;\n  @include border-radius($tooltip-border-radius);\n}\n","@mixin reset-text() {\n  font-family: $font-family-base;\n  // We deliberately do NOT reset font-size or word-wrap.\n  font-style: normal;\n  font-weight: $font-weight-normal;\n  line-height: $line-height-base;\n  text-align: left; // Fallback for where `start` is not supported\n  text-align: start;\n  text-decoration: none;\n  text-shadow: none;\n  text-transform: none;\n  letter-spacing: normal;\n  word-break: normal;\n  word-spacing: normal;\n  white-space: normal;\n  line-break: auto;\n}\n",".popover {\n  position: absolute;\n  top: 0;\n  left: 0;\n  z-index: $zindex-popover;\n  display: block;\n  max-width: $popover-max-width;\n  // Our parent element can be arbitrary since tooltips are by default inserted as a sibling of their target element.\n  // So reset our font and text properties to avoid inheriting weird values.\n  @include reset-text();\n  @include font-size($popover-font-size);\n  // Allow breaking very long words so they don't overflow the popover's bounds\n  word-wrap: break-word;\n  background-color: $popover-bg;\n  background-clip: padding-box;\n  border: $popover-border-width solid $popover-border-color;\n  @include border-radius($popover-border-radius);\n  @include box-shadow($popover-box-shadow);\n\n  .arrow {\n    position: absolute;\n    display: block;\n    width: $popover-arrow-width;\n    height: $popover-arrow-height;\n    margin: 0 $popover-border-radius;\n\n    &::before,\n    &::after {\n      position: absolute;\n      display: block;\n      content: \"\";\n      border-color: transparent;\n      border-style: solid;\n    }\n  }\n}\n\n.bs-popover-top {\n  margin-bottom: $popover-arrow-height;\n\n  > .arrow {\n    bottom: subtract(-$popover-arrow-height, $popover-border-width);\n\n    &::before {\n      bottom: 0;\n      border-width: $popover-arrow-height ($popover-arrow-width * .5) 0;\n      border-top-color: $popover-arrow-outer-color;\n    }\n\n    &::after {\n      bottom: $popover-border-width;\n      border-width: $popover-arrow-height ($popover-arrow-width * .5) 0;\n      border-top-color: $popover-arrow-color;\n    }\n  }\n}\n\n.bs-popover-right {\n  margin-left: $popover-arrow-height;\n\n  > .arrow {\n    left: subtract(-$popover-arrow-height, $popover-border-width);\n    width: $popover-arrow-height;\n    height: $popover-arrow-width;\n    margin: $popover-border-radius 0; // make sure the arrow does not touch the popover's rounded corners\n\n    &::before {\n      left: 0;\n      border-width: ($popover-arrow-width * .5) $popover-arrow-height ($popover-arrow-width * .5) 0;\n      border-right-color: $popover-arrow-outer-color;\n    }\n\n    &::after {\n      left: $popover-border-width;\n      border-width: ($popover-arrow-width * .5) $popover-arrow-height ($popover-arrow-width * .5) 0;\n      border-right-color: $popover-arrow-color;\n    }\n  }\n}\n\n.bs-popover-bottom {\n  margin-top: $popover-arrow-height;\n\n  > .arrow {\n    top: subtract(-$popover-arrow-height, $popover-border-width);\n\n    &::before {\n      top: 0;\n      border-width: 0 ($popover-arrow-width * .5) $popover-arrow-height ($popover-arrow-width * .5);\n      border-bottom-color: $popover-arrow-outer-color;\n    }\n\n    &::after {\n      top: $popover-border-width;\n      border-width: 0 ($popover-arrow-width * .5) $popover-arrow-height ($popover-arrow-width * .5);\n      border-bottom-color: $popover-arrow-color;\n    }\n  }\n\n  // This will remove the popover-header's border just below the arrow\n  .popover-header::before {\n    position: absolute;\n    top: 0;\n    left: 50%;\n    display: block;\n    width: $popover-arrow-width;\n    margin-left: -$popover-arrow-width * .5;\n    content: \"\";\n    border-bottom: $popover-border-width solid $popover-header-bg;\n  }\n}\n\n.bs-popover-left {\n  margin-right: $popover-arrow-height;\n\n  > .arrow {\n    right: subtract(-$popover-arrow-height, $popover-border-width);\n    width: $popover-arrow-height;\n    height: $popover-arrow-width;\n    margin: $popover-border-radius 0; // make sure the arrow does not touch the popover's rounded corners\n\n    &::before {\n      right: 0;\n      border-width: ($popover-arrow-width * .5) 0 ($popover-arrow-width * .5) $popover-arrow-height;\n      border-left-color: $popover-arrow-outer-color;\n    }\n\n    &::after {\n      right: $popover-border-width;\n      border-width: ($popover-arrow-width * .5) 0 ($popover-arrow-width * .5) $popover-arrow-height;\n      border-left-color: $popover-arrow-color;\n    }\n  }\n}\n\n.bs-popover-auto {\n  &[x-placement^=\"top\"] {\n    @extend .bs-popover-top;\n  }\n  &[x-placement^=\"right\"] {\n    @extend .bs-popover-right;\n  }\n  &[x-placement^=\"bottom\"] {\n    @extend .bs-popover-bottom;\n  }\n  &[x-placement^=\"left\"] {\n    @extend .bs-popover-left;\n  }\n}\n\n\n// Offset the popover to account for the popover arrow\n.popover-header {\n  padding: $popover-header-padding-y $popover-header-padding-x;\n  margin-bottom: 0; // Reset the default from Reboot\n  @include font-size($font-size-base);\n  color: $popover-header-color;\n  background-color: $popover-header-bg;\n  border-bottom: $popover-border-width solid darken($popover-header-bg, 5%);\n  @include border-top-radius($popover-inner-border-radius);\n\n  &:empty {\n    display: none;\n  }\n}\n\n.popover-body {\n  padding: $popover-body-padding-y $popover-body-padding-x;\n  color: $popover-body-color;\n}\n","// Notes on the classes:\n//\n// 1. .carousel.pointer-event should ideally be pan-y (to allow for users to scroll vertically)\n//    even when their scroll action started on a carousel, but for compatibility (with Firefox)\n//    we're preventing all actions instead\n// 2. The .carousel-item-left and .carousel-item-right is used to indicate where\n//    the active slide is heading.\n// 3. .active.carousel-item is the current slide.\n// 4. .active.carousel-item-left and .active.carousel-item-right is the current\n//    slide in its in-transition state. Only one of these occurs at a time.\n// 5. .carousel-item-next.carousel-item-left and .carousel-item-prev.carousel-item-right\n//    is the upcoming slide in transition.\n\n.carousel {\n  position: relative;\n}\n\n.carousel.pointer-event {\n  touch-action: pan-y;\n}\n\n.carousel-inner {\n  position: relative;\n  width: 100%;\n  overflow: hidden;\n  @include clearfix();\n}\n\n.carousel-item {\n  position: relative;\n  display: none;\n  float: left;\n  width: 100%;\n  margin-right: -100%;\n  backface-visibility: hidden;\n  @include transition($carousel-transition);\n}\n\n.carousel-item.active,\n.carousel-item-next,\n.carousel-item-prev {\n  display: block;\n}\n\n.carousel-item-next:not(.carousel-item-left),\n.active.carousel-item-right {\n  transform: translateX(100%);\n}\n\n.carousel-item-prev:not(.carousel-item-right),\n.active.carousel-item-left {\n  transform: translateX(-100%);\n}\n\n\n//\n// Alternate transitions\n//\n\n.carousel-fade {\n  .carousel-item {\n    opacity: 0;\n    transition-property: opacity;\n    transform: none;\n  }\n\n  .carousel-item.active,\n  .carousel-item-next.carousel-item-left,\n  .carousel-item-prev.carousel-item-right {\n    z-index: 1;\n    opacity: 1;\n  }\n\n  .active.carousel-item-left,\n  .active.carousel-item-right {\n    z-index: 0;\n    opacity: 0;\n    @include transition(opacity 0s $carousel-transition-duration);\n  }\n}\n\n\n//\n// Left/right controls for nav\n//\n\n.carousel-control-prev,\n.carousel-control-next {\n  position: absolute;\n  top: 0;\n  bottom: 0;\n  z-index: 1;\n  // Use flex for alignment (1-3)\n  display: flex; // 1. allow flex styles\n  align-items: center; // 2. vertically center contents\n  justify-content: center; // 3. horizontally center contents\n  width: $carousel-control-width;\n  padding: 0;\n  color: $carousel-control-color;\n  text-align: center;\n  background: none;\n  border: 0;\n  opacity: $carousel-control-opacity;\n  @include transition($carousel-control-transition);\n\n  // Hover/focus state\n  @include hover-focus() {\n    color: $carousel-control-color;\n    text-decoration: none;\n    outline: 0;\n    opacity: $carousel-control-hover-opacity;\n  }\n}\n.carousel-control-prev {\n  left: 0;\n  @if $enable-gradients {\n    background-image: linear-gradient(90deg, rgba($black, .25), rgba($black, .001));\n  }\n}\n.carousel-control-next {\n  right: 0;\n  @if $enable-gradients {\n    background-image: linear-gradient(270deg, rgba($black, .25), rgba($black, .001));\n  }\n}\n\n// Icons for within\n.carousel-control-prev-icon,\n.carousel-control-next-icon {\n  display: inline-block;\n  width: $carousel-control-icon-width;\n  height: $carousel-control-icon-width;\n  background: 50% / 100% 100% no-repeat;\n}\n.carousel-control-prev-icon {\n  background-image: escape-svg($carousel-control-prev-icon-bg);\n}\n.carousel-control-next-icon {\n  background-image: escape-svg($carousel-control-next-icon-bg);\n}\n\n\n// Optional indicator pips\n//\n// Add an ordered list with the following class and add a list item for each\n// slide your carousel holds.\n\n.carousel-indicators {\n  position: absolute;\n  right: 0;\n  bottom: 0;\n  left: 0;\n  z-index: 15;\n  display: flex;\n  justify-content: center;\n  padding-left: 0; // override <ol> default\n  // Use the .carousel-control's width as margin so we don't overlay those\n  margin-right: $carousel-control-width;\n  margin-left: $carousel-control-width;\n  list-style: none;\n\n  li {\n    box-sizing: content-box;\n    flex: 0 1 auto;\n    width: $carousel-indicator-width;\n    height: $carousel-indicator-height;\n    margin-right: $carousel-indicator-spacer;\n    margin-left: $carousel-indicator-spacer;\n    text-indent: -999px;\n    cursor: pointer;\n    background-color: $carousel-indicator-active-bg;\n    background-clip: padding-box;\n    // Use transparent borders to increase the hit area by 10px on top and bottom.\n    border-top: $carousel-indicator-hit-area-height solid transparent;\n    border-bottom: $carousel-indicator-hit-area-height solid transparent;\n    opacity: .5;\n    @include transition($carousel-indicator-transition);\n  }\n\n  .active {\n    opacity: 1;\n  }\n}\n\n\n// Optional captions\n//\n//\n\n.carousel-caption {\n  position: absolute;\n  right: (100% - $carousel-caption-width) * .5;\n  bottom: 20px;\n  left: (100% - $carousel-caption-width) * .5;\n  z-index: 10;\n  padding-top: 20px;\n  padding-bottom: 20px;\n  color: $carousel-caption-color;\n  text-align: center;\n}\n","@mixin clearfix() {\n  &::after {\n    display: block;\n    clear: both;\n    content: \"\";\n  }\n}\n","//\n// Rotating border\n//\n\n@keyframes spinner-border {\n  to { transform: rotate(360deg); }\n}\n\n.spinner-border {\n  display: inline-block;\n  width: $spinner-width;\n  height: $spinner-height;\n  vertical-align: $spinner-vertical-align;\n  border: $spinner-border-width solid currentColor;\n  border-right-color: transparent;\n  // stylelint-disable-next-line property-disallowed-list\n  border-radius: 50%;\n  animation: .75s linear infinite spinner-border;\n}\n\n.spinner-border-sm {\n  width: $spinner-width-sm;\n  height: $spinner-height-sm;\n  border-width: $spinner-border-width-sm;\n}\n\n//\n// Growing circle\n//\n\n@keyframes spinner-grow {\n  0% {\n    transform: scale(0);\n  }\n  50% {\n    opacity: 1;\n    transform: none;\n  }\n}\n\n.spinner-grow {\n  display: inline-block;\n  width: $spinner-width;\n  height: $spinner-height;\n  vertical-align: $spinner-vertical-align;\n  background-color: currentColor;\n  // stylelint-disable-next-line property-disallowed-list\n  border-radius: 50%;\n  opacity: 0;\n  animation: .75s linear infinite spinner-grow;\n}\n\n.spinner-grow-sm {\n  width: $spinner-width-sm;\n  height: $spinner-height-sm;\n}\n\n@if $enable-prefers-reduced-motion-media-query {\n  @media (prefers-reduced-motion: reduce) {\n    .spinner-border,\n    .spinner-grow {\n      animation-duration: 1.5s;\n    }\n  }\n}\n","// stylelint-disable declaration-no-important\n\n.align-baseline    { vertical-align: baseline !important; } // Browser default\n.align-top         { vertical-align: top !important; }\n.align-middle      { vertical-align: middle !important; }\n.align-bottom      { vertical-align: bottom !important; }\n.align-text-bottom { vertical-align: text-bottom !important; }\n.align-text-top    { vertical-align: text-top !important; }\n","// stylelint-disable declaration-no-important\n\n// Contextual backgrounds\n\n@mixin bg-variant($parent, $color, $ignore-warning: false) {\n  #{$parent} {\n    background-color: $color !important;\n  }\n  a#{$parent},\n  button#{$parent} {\n    @include hover-focus() {\n      background-color: darken($color, 10%) !important;\n    }\n  }\n  @include deprecate(\"The `bg-variant` mixin\", \"v4.4.0\", \"v5\", $ignore-warning);\n}\n\n@mixin bg-gradient-variant($parent, $color, $ignore-warning: false) {\n  #{$parent} {\n    background: $color linear-gradient(180deg, mix($body-bg, $color, 15%), $color) repeat-x !important;\n  }\n  @include deprecate(\"The `bg-gradient-variant` mixin\", \"v4.5.0\", \"v5\", $ignore-warning);\n}\n","// stylelint-disable declaration-no-important\n\n@each $color, $value in $theme-colors {\n  @include bg-variant(\".bg-#{$color}\", $value, true);\n}\n\n@if $enable-gradients {\n  @each $color, $value in $theme-colors {\n    @include bg-gradient-variant(\".bg-gradient-#{$color}\", $value, true);\n  }\n}\n\n.bg-white {\n  background-color: $white !important;\n}\n\n.bg-transparent {\n  background-color: transparent !important;\n}\n","// stylelint-disable property-disallowed-list, declaration-no-important\n\n//\n// Border\n//\n\n.border         { border: $border-width solid $border-color !important; }\n.border-top     { border-top: $border-width solid $border-color !important; }\n.border-right   { border-right: $border-width solid $border-color !important; }\n.border-bottom  { border-bottom: $border-width solid $border-color !important; }\n.border-left    { border-left: $border-width solid $border-color !important; }\n\n.border-0        { border: 0 !important; }\n.border-top-0    { border-top: 0 !important; }\n.border-right-0  { border-right: 0 !important; }\n.border-bottom-0 { border-bottom: 0 !important; }\n.border-left-0   { border-left: 0 !important; }\n\n@each $color, $value in $theme-colors {\n  .border-#{$color} {\n    border-color: $value !important;\n  }\n}\n\n.border-white {\n  border-color: $white !important;\n}\n\n//\n// Border-radius\n//\n\n.rounded-sm {\n  border-radius: $border-radius-sm !important;\n}\n\n.rounded {\n  border-radius: $border-radius !important;\n}\n\n.rounded-top {\n  border-top-left-radius: $border-radius !important;\n  border-top-right-radius: $border-radius !important;\n}\n\n.rounded-right {\n  border-top-right-radius: $border-radius !important;\n  border-bottom-right-radius: $border-radius !important;\n}\n\n.rounded-bottom {\n  border-bottom-right-radius: $border-radius !important;\n  border-bottom-left-radius: $border-radius !important;\n}\n\n.rounded-left {\n  border-top-left-radius: $border-radius !important;\n  border-bottom-left-radius: $border-radius !important;\n}\n\n.rounded-lg {\n  border-radius: $border-radius-lg !important;\n}\n\n.rounded-circle {\n  border-radius: 50% !important;\n}\n\n.rounded-pill {\n  border-radius: $rounded-pill !important;\n}\n\n.rounded-0 {\n  border-radius: 0 !important;\n}\n","// stylelint-disable declaration-no-important\n\n//\n// Utilities for common `display` values\n//\n\n@each $breakpoint in map-keys($grid-breakpoints) {\n  @include media-breakpoint-up($breakpoint) {\n    $infix: breakpoint-infix($breakpoint, $grid-breakpoints);\n\n    @each $value in $displays {\n      .d#{$infix}-#{$value} { display: $value !important; }\n    }\n  }\n}\n\n\n//\n// Utilities for toggling `display` in print\n//\n\n@media print {\n  @each $value in $displays {\n    .d-print-#{$value} { display: $value !important; }\n  }\n}\n","// Credit: Nicolas Gallagher and SUIT CSS.\n\n.embed-responsive {\n  position: relative;\n  display: block;\n  width: 100%;\n  padding: 0;\n  overflow: hidden;\n\n  &::before {\n    display: block;\n    content: \"\";\n  }\n\n  .embed-responsive-item,\n  iframe,\n  embed,\n  object,\n  video {\n    position: absolute;\n    top: 0;\n    bottom: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    border: 0;\n  }\n}\n\n@each $embed-responsive-aspect-ratio in $embed-responsive-aspect-ratios {\n  $embed-responsive-aspect-ratio-x: nth($embed-responsive-aspect-ratio, 1);\n  $embed-responsive-aspect-ratio-y: nth($embed-responsive-aspect-ratio, 2);\n\n  .embed-responsive-#{$embed-responsive-aspect-ratio-x}by#{$embed-responsive-aspect-ratio-y} {\n    &::before {\n      padding-top: percentage(divide($embed-responsive-aspect-ratio-y, $embed-responsive-aspect-ratio-x));\n    }\n  }\n}\n","// stylelint-disable declaration-no-important\n\n// Flex variation\n//\n// Custom styles for additional flex alignment options.\n\n@each $breakpoint in map-keys($grid-breakpoints) {\n  @include media-breakpoint-up($breakpoint) {\n    $infix: breakpoint-infix($breakpoint, $grid-breakpoints);\n\n    .flex#{$infix}-row            { flex-direction: row !important; }\n    .flex#{$infix}-column         { flex-direction: column !important; }\n    .flex#{$infix}-row-reverse    { flex-direction: row-reverse !important; }\n    .flex#{$infix}-column-reverse { flex-direction: column-reverse !important; }\n\n    .flex#{$infix}-wrap         { flex-wrap: wrap !important; }\n    .flex#{$infix}-nowrap       { flex-wrap: nowrap !important; }\n    .flex#{$infix}-wrap-reverse { flex-wrap: wrap-reverse !important; }\n    .flex#{$infix}-fill         { flex: 1 1 auto !important; }\n    .flex#{$infix}-grow-0       { flex-grow: 0 !important; }\n    .flex#{$infix}-grow-1       { flex-grow: 1 !important; }\n    .flex#{$infix}-shrink-0     { flex-shrink: 0 !important; }\n    .flex#{$infix}-shrink-1     { flex-shrink: 1 !important; }\n\n    .justify-content#{$infix}-start   { justify-content: flex-start !important; }\n    .justify-content#{$infix}-end     { justify-content: flex-end !important; }\n    .justify-content#{$infix}-center  { justify-content: center !important; }\n    .justify-content#{$infix}-between { justify-content: space-between !important; }\n    .justify-content#{$infix}-around  { justify-content: space-around !important; }\n\n    .align-items#{$infix}-start    { align-items: flex-start !important; }\n    .align-items#{$infix}-end      { align-items: flex-end !important; }\n    .align-items#{$infix}-center   { align-items: center !important; }\n    .align-items#{$infix}-baseline { align-items: baseline !important; }\n    .align-items#{$infix}-stretch  { align-items: stretch !important; }\n\n    .align-content#{$infix}-start   { align-content: flex-start !important; }\n    .align-content#{$infix}-end     { align-content: flex-end !important; }\n    .align-content#{$infix}-center  { align-content: center !important; }\n    .align-content#{$infix}-between { align-content: space-between !important; }\n    .align-content#{$infix}-around  { align-content: space-around !important; }\n    .align-content#{$infix}-stretch { align-content: stretch !important; }\n\n    .align-self#{$infix}-auto     { align-self: auto !important; }\n    .align-self#{$infix}-start    { align-self: flex-start !important; }\n    .align-self#{$infix}-end      { align-self: flex-end !important; }\n    .align-self#{$infix}-center   { align-self: center !important; }\n    .align-self#{$infix}-baseline { align-self: baseline !important; }\n    .align-self#{$infix}-stretch  { align-self: stretch !important; }\n  }\n}\n","// stylelint-disable declaration-no-important\n\n@each $breakpoint in map-keys($grid-breakpoints) {\n  @include media-breakpoint-up($breakpoint) {\n    $infix: breakpoint-infix($breakpoint, $grid-breakpoints);\n\n    .float#{$infix}-left  { float: left !important; }\n    .float#{$infix}-right { float: right !important; }\n    .float#{$infix}-none  { float: none !important; }\n  }\n}\n","// stylelint-disable declaration-no-important\n\n@each $value in $user-selects {\n  .user-select-#{$value} { user-select: $value !important; }\n}\n","// stylelint-disable declaration-no-important\n\n@each $value in $overflows {\n  .overflow-#{$value} { overflow: $value !important; }\n}\n","// stylelint-disable declaration-no-important\n\n// Common values\n@each $position in $positions {\n  .position-#{$position} { position: $position !important; }\n}\n\n// Shorthand\n\n.fixed-top {\n  position: fixed;\n  top: 0;\n  right: 0;\n  left: 0;\n  z-index: $zindex-fixed;\n}\n\n.fixed-bottom {\n  position: fixed;\n  right: 0;\n  bottom: 0;\n  left: 0;\n  z-index: $zindex-fixed;\n}\n\n.sticky-top {\n  @supports (position: sticky) {\n    position: sticky;\n    top: 0;\n    z-index: $zindex-sticky;\n  }\n}\n","//\n// Screenreaders\n//\n\n.sr-only {\n  @include sr-only();\n}\n\n.sr-only-focusable {\n  @include sr-only-focusable();\n}\n","// Only display content to screen readers\n//\n// See: https://www.a11yproject.com/posts/2013-01-11-how-to-hide-content/\n// See: https://kittygiraudel.com/2016/10/13/css-hide-and-seek/\n\n@mixin sr-only() {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px; // Fix for https://github.com/twbs/bootstrap/issues/25686\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n  white-space: nowrap;\n  border: 0;\n}\n\n// Use in conjunction with .sr-only to only display content when it's focused.\n//\n// Useful for \"Skip to main content\" links; see https://www.w3.org/TR/2013/NOTE-WCAG20-TECHS-20130905/G1\n//\n// Credit: HTML5 Boilerplate\n\n@mixin sr-only-focusable() {\n  &:active,\n  &:focus {\n    position: static;\n    width: auto;\n    height: auto;\n    overflow: visible;\n    clip: auto;\n    white-space: normal;\n  }\n}\n","// stylelint-disable declaration-no-important\n\n.shadow-sm { box-shadow: $box-shadow-sm !important; }\n.shadow { box-shadow: $box-shadow !important; }\n.shadow-lg { box-shadow: $box-shadow-lg !important; }\n.shadow-none { box-shadow: none !important; }\n","// stylelint-disable declaration-no-important\n\n// Width and height\n\n@each $prop, $abbrev in (width: w, height: h) {\n  @each $size, $length in $sizes {\n    .#{$abbrev}-#{$size} { #{$prop}: $length !important; }\n  }\n}\n\n.mw-100 { max-width: 100% !important; }\n.mh-100 { max-height: 100% !important; }\n\n// Viewport additional helpers\n\n.min-vw-100 { min-width: 100vw !important; }\n.min-vh-100 { min-height: 100vh !important; }\n\n.vw-100 { width: 100vw !important; }\n.vh-100 { height: 100vh !important; }\n","// stylelint-disable declaration-no-important\n\n// Margin and Padding\n\n@each $breakpoint in map-keys($grid-breakpoints) {\n  @include media-breakpoint-up($breakpoint) {\n    $infix: breakpoint-infix($breakpoint, $grid-breakpoints);\n\n    @each $prop, $abbrev in (margin: m, padding: p) {\n      @each $size, $length in $spacers {\n        .#{$abbrev}#{$infix}-#{$size} { #{$prop}: $length !important; }\n        .#{$abbrev}t#{$infix}-#{$size},\n        .#{$abbrev}y#{$infix}-#{$size} {\n          #{$prop}-top: $length !important;\n        }\n        .#{$abbrev}r#{$infix}-#{$size},\n        .#{$abbrev}x#{$infix}-#{$size} {\n          #{$prop}-right: $length !important;\n        }\n        .#{$abbrev}b#{$infix}-#{$size},\n        .#{$abbrev}y#{$infix}-#{$size} {\n          #{$prop}-bottom: $length !important;\n        }\n        .#{$abbrev}l#{$infix}-#{$size},\n        .#{$abbrev}x#{$infix}-#{$size} {\n          #{$prop}-left: $length !important;\n        }\n      }\n    }\n\n    // Negative margins (e.g., where `.mb-n1` is negative version of `.mb-1`)\n    @each $size, $length in $spacers {\n      @if \"#{$size}\" != \"0\" {\n        .m#{$infix}-n#{$size} { margin: -$length !important; }\n        .mt#{$infix}-n#{$size},\n        .my#{$infix}-n#{$size} {\n          margin-top: -$length !important;\n        }\n        .mr#{$infix}-n#{$size},\n        .mx#{$infix}-n#{$size} {\n          margin-right: -$length !important;\n        }\n        .mb#{$infix}-n#{$size},\n        .my#{$infix}-n#{$size} {\n          margin-bottom: -$length !important;\n        }\n        .ml#{$infix}-n#{$size},\n        .mx#{$infix}-n#{$size} {\n          margin-left: -$length !important;\n        }\n      }\n    }\n\n    // Some special margin utils\n    .m#{$infix}-auto { margin: auto !important; }\n    .mt#{$infix}-auto,\n    .my#{$infix}-auto {\n      margin-top: auto !important;\n    }\n    .mr#{$infix}-auto,\n    .mx#{$infix}-auto {\n      margin-right: auto !important;\n    }\n    .mb#{$infix}-auto,\n    .my#{$infix}-auto {\n      margin-bottom: auto !important;\n    }\n    .ml#{$infix}-auto,\n    .mx#{$infix}-auto {\n      margin-left: auto !important;\n    }\n  }\n}\n","//\n// Stretched link\n//\n\n.stretched-link {\n  &::after {\n    position: absolute;\n    top: 0;\n    right: 0;\n    bottom: 0;\n    left: 0;\n    z-index: 1;\n    // Just in case `pointer-events: none` is set on a parent\n    pointer-events: auto;\n    content: \"\";\n    // IE10 bugfix, see https://stackoverflow.com/questions/16947967/ie10-hover-pseudo-class-doesnt-work-without-background-color\n    background-color: rgba(0, 0, 0, 0);\n  }\n}\n","// stylelint-disable declaration-no-important\n\n//\n// Text\n//\n\n.text-monospace { font-family: $font-family-monospace !important; }\n\n// Alignment\n\n.text-justify  { text-align: justify !important; }\n.text-wrap     { white-space: normal !important; }\n.text-nowrap   { white-space: nowrap !important; }\n.text-truncate { @include text-truncate(); }\n\n// Responsive alignment\n\n@each $breakpoint in map-keys($grid-breakpoints) {\n  @include media-breakpoint-up($breakpoint) {\n    $infix: breakpoint-infix($breakpoint, $grid-breakpoints);\n\n    .text#{$infix}-left   { text-align: left !important; }\n    .text#{$infix}-right  { text-align: right !important; }\n    .text#{$infix}-center { text-align: center !important; }\n  }\n}\n\n// Transformation\n\n.text-lowercase  { text-transform: lowercase !important; }\n.text-uppercase  { text-transform: uppercase !important; }\n.text-capitalize { text-transform: capitalize !important; }\n\n// Weight and italics\n\n.font-weight-light   { font-weight: $font-weight-light !important; }\n.font-weight-lighter { font-weight: $font-weight-lighter !important; }\n.font-weight-normal  { font-weight: $font-weight-normal !important; }\n.font-weight-bold    { font-weight: $font-weight-bold !important; }\n.font-weight-bolder  { font-weight: $font-weight-bolder !important; }\n.font-italic         { font-style: italic !important; }\n\n// Contextual colors\n\n.text-white { color: $white !important; }\n\n@each $color, $value in $theme-colors {\n  @include text-emphasis-variant(\".text-#{$color}\", $value, true);\n}\n\n.text-body { color: $body-color !important; }\n.text-muted { color: $text-muted !important; }\n\n.text-black-50 { color: rgba($black, .5) !important; }\n.text-white-50 { color: rgba($white, .5) !important; }\n\n// Misc\n\n.text-hide {\n  @include text-hide($ignore-warning: true);\n}\n\n.text-decoration-none { text-decoration: none !important; }\n\n.text-break {\n  word-break: break-word !important; // Deprecated, but avoids issues with flex containers\n  word-wrap: break-word !important; // Used instead of `overflow-wrap` for IE & Edge Legacy\n}\n\n// Reset\n\n.text-reset { color: inherit !important; }\n","// Text truncate\n// Requires inline-block or block for proper styling\n\n@mixin text-truncate() {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n","// stylelint-disable declaration-no-important\n\n// Typography\n\n@mixin text-emphasis-variant($parent, $color, $ignore-warning: false) {\n  #{$parent} {\n    color: $color !important;\n  }\n  @if $emphasized-link-hover-darken-percentage != 0 {\n    a#{$parent} {\n      @include hover-focus() {\n        color: darken($color, $emphasized-link-hover-darken-percentage) !important;\n      }\n    }\n  }\n  @include deprecate(\"`text-emphasis-variant()`\", \"v4.4.0\", \"v5\", $ignore-warning);\n}\n","// CSS image replacement\n@mixin text-hide($ignore-warning: false) {\n  // stylelint-disable-next-line font-family-no-missing-generic-family-keyword\n  font: 0/0 a;\n  color: transparent;\n  text-shadow: none;\n  background-color: transparent;\n  border: 0;\n\n  @include deprecate(\"`text-hide()`\", \"v4.1.0\", \"v5\", $ignore-warning);\n}\n","// stylelint-disable declaration-no-important\n\n//\n// Visibility utilities\n//\n\n.visible {\n  visibility: visible !important;\n}\n\n.invisible {\n  visibility: hidden !important;\n}\n","// stylelint-disable declaration-no-important, selector-no-qualifying-type\n\n// Source: https://github.com/h5bp/main.css/blob/master/src/_print.css\n\n// ==========================================================================\n// Print styles.\n// Inlined to avoid the additional HTTP request:\n// https://www.phpied.com/delay-loading-your-print-css/\n// ==========================================================================\n\n@if $enable-print-styles {\n  @media print {\n    *,\n    *::before,\n    *::after {\n      // Bootstrap specific; comment out `color` and `background`\n      //color: $black !important; // Black prints faster\n      text-shadow: none !important;\n      //background: transparent !important;\n      box-shadow: none !important;\n    }\n\n    a {\n      &:not(.btn) {\n        text-decoration: underline;\n      }\n    }\n\n    // Bootstrap specific; comment the following selector out\n    //a[href]::after {\n    //  content: \" (\" attr(href) \")\";\n    //}\n\n    abbr[title]::after {\n      content: \" (\" attr(title) \")\";\n    }\n\n    // Bootstrap specific; comment the following selector out\n    //\n    // Don't show links that are fragment identifiers,\n    // or use the `javascript:` pseudo protocol\n    //\n\n    //a[href^=\"#\"]::after,\n    //a[href^=\"javascript:\"]::after {\n    // content: \"\";\n    //}\n\n    pre {\n      white-space: pre-wrap !important;\n    }\n    pre,\n    blockquote {\n      border: $border-width solid $gray-500; // Bootstrap custom code; using `$border-width` instead of 1px\n      page-break-inside: avoid;\n    }\n\n    tr,\n    img {\n      page-break-inside: avoid;\n    }\n\n    p,\n    h2,\n    h3 {\n      orphans: 3;\n      widows: 3;\n    }\n\n    h2,\n    h3 {\n      page-break-after: avoid;\n    }\n\n    // Bootstrap specific changes start\n\n    // Specify a size and min-width to make printing closer across browsers.\n    // We don't set margin here because it breaks `size` in Chrome. We also\n    // don't use `!important` on `size` as it breaks in Chrome.\n    @page {\n      size: $print-page-size;\n    }\n    body {\n      min-width: $print-body-min-width !important;\n    }\n    .container {\n      min-width: $print-body-min-width !important;\n    }\n\n    // Bootstrap components\n    .navbar {\n      display: none;\n    }\n    .badge {\n      border: $border-width solid $black;\n    }\n\n    .table {\n      border-collapse: collapse !important;\n\n      td,\n      th {\n        background-color: $white !important;\n      }\n    }\n\n    .table-bordered {\n      th,\n      td {\n        border: 1px solid $gray-300 !important;\n      }\n    }\n\n    .table-dark {\n      color: inherit;\n\n      th,\n      td,\n      thead th,\n      tbody + tbody {\n        border-color: $table-border-color;\n      }\n    }\n\n    .table .thead-dark th {\n      color: inherit;\n      border-color: $table-border-color;\n    }\n\n    // Bootstrap specific changes end\n  }\n}\n","//\n// Mixins: Animation\n//\n\n\n@keyframes flipInX {\n  0% {\n    transform: perspective(400px) rotate3d(1, 0, 0, 90deg);\n    transition-timing-function: ease-in;\n    opacity: 0;\n  }\n\n  40% {\n    transform: perspective(400px) rotate3d(1, 0, 0, -20deg);\n    transition-timing-function: ease-in;\n  }\n\n  60% {\n    transform: perspective(400px) rotate3d(1, 0, 0, 10deg);\n    opacity: 1;\n  }\n\n  80% {\n    transform: perspective(400px) rotate3d(1, 0, 0, -5deg);\n  }\n\n  100% {\n    transform: perspective(400px);\n  }\n}\n\n\n@keyframes fadeIn {\n  from {\n    opacity: 0;\n  }\n\n  to {\n    opacity: 1;\n  }\n}\n\n@keyframes fadeOut {\n  from {\n    opacity: 1;\n  }\n\n  to {\n    opacity: 0;\n  }\n}\n\n@keyframes shake {\n  0% {\n    transform: translate(2px, 1px) rotate(0deg);\n  }\n  10% {\n    transform: translate(-1px, -2px) rotate(-2deg);\n  }\n  20% {\n    transform: translate(-3px, 0) rotate(3deg);\n  }\n  30% {\n    transform: translate(0, 2px) rotate(0deg);\n  }\n  40% {\n    transform: translate(1px, -1px) rotate(1deg);\n  }\n  50% {\n    transform: translate(-1px, 2px) rotate(-1deg);\n  }\n  60% {\n    transform: translate(-3px, 1px) rotate(0deg);\n  }\n  70% {\n    transform: translate(2px, 1px) rotate(-2deg);\n  }\n  80% {\n    transform: translate(-1px, -1px) rotate(4deg);\n  }\n  90% {\n    transform: translate(2px, 2px) rotate(0deg);\n  }\n  100% {\n    transform: translate(1px, -2px) rotate(-1deg);\n  }\n}\n\n@keyframes wobble {\n  0% {\n    transform: none;\n  }\n\n  15% {\n    transform: translate3d(-25%, 0, 0) rotate3d(0, 0, 1, -5deg);\n  }\n\n  30% {\n    transform: translate3d(20%, 0, 0) rotate3d(0, 0, 1, 3deg);\n  }\n\n  45% {\n    transform: translate3d(-15%, 0, 0) rotate3d(0, 0, 1, -3deg);\n  }\n\n  60% {\n    transform: translate3d(10%, 0, 0) rotate3d(0, 0, 1, 2deg);\n  }\n\n  75% {\n    transform: translate3d(-5%, 0, 0) rotate3d(0, 0, 1, -1deg);\n  }\n\n  100% {\n    transform: none;\n  }\n}\n\n//\n","//\n// Mixins: Dark Mode Controll\n//\n\n@mixin dark-mode {\n  @if $enable-dark-mode {\n    .dark-mode {\n      @content;\n    }\n  }\n}\n","@include dark-mode () {\n  :root {\n    // Custom variable values only support SassScript inside `#{}`.\n    @each $color, $value in $colors-alt {\n      --#{$color}: #{$value};\n    }\n\n    @each $color, $value in $theme-colors-alt {\n      --#{$color}: #{$value};\n    }\n  }\n}\n\n//\n","//\n// Component: Animation\n//\n\n.animation {\n  &__shake {\n    animation: shake 1500ms;\n  }\n  &__wobble {\n    animation: wobble 1500ms;\n  }\n}\n\n//\n","//\n// Core: Preloader\n//\n\n.preloader {\n  display: flex;\n  background-color: $main-bg;\n  height: 100vh;\n  width: 100%;\n  transition: height 200ms linear;\n  position: fixed;\n  left: 0;\n  top: 0;\n  z-index: $zindex-preloader;\n}\n\n@include dark-mode () {\n  .preloader {\n    background-color: $dark-main-bg;\n    color: $white;\n  }\n}\n\n//\n","//\n// Core: Layout\n//\n\nhtml.scroll-smooth {\n  scroll-behavior: smooth;\n}\n\nhtml,\nbody,\n.wrapper {\n  min-height: 100%;\n}\n\n.wrapper {\n  position: relative;\n\n  .content-wrapper {\n    min-height: calc(100vh - #{$main-header-height} - #{$main-footer-height});\n  }\n\n  .layout-boxed & {\n    @include box-shadow(0 0 10 rgba($black, .3));\n\n    &,\n    &::before {\n      margin: 0 auto;\n      max-width: $boxed-layout-max-width;\n      overflow: hidden;\n    }\n\n    .main-sidebar {\n      left: inherit;\n    }\n  }\n\n  @supports not (-webkit-touch-callout: none) {\n    .layout-fixed & .sidebar {\n      height: calc(100vh - (#{$main-header-height-inner} + #{$main-header-bottom-border-width}));\n    }\n    .layout-fixed.text-sm & .sidebar {\n      height: calc(100vh - (#{$main-header-height-sm-inner} + #{$main-header-bottom-border-width}));\n    }\n  }\n\n  .layout-navbar-fixed.layout-fixed & {\n    .control-sidebar {\n      top: $main-header-height;\n    }\n\n    .main-header.text-sm ~ .control-sidebar {\n      top: $main-header-height-sm;\n    }\n\n    .sidebar {\n      margin-top: $main-header-height;\n    }\n\n    .brand-link.text-sm ~ .sidebar {\n      margin-top: $main-header-height-sm;\n    }\n  }\n\n  .layout-navbar-fixed.layout-fixed.text-sm & {\n    .control-sidebar {\n      top: $main-header-height-sm;\n    }\n\n    .sidebar {\n      margin-top: $main-header-height-sm;\n    }\n  }\n\n  .layout-navbar-fixed.sidebar-mini.sidebar-collapse &,\n  .layout-navbar-fixed.sidebar-mini-md.sidebar-collapse &,\n  .layout-navbar-fixed.sidebar-mini-xs.sidebar-collapse & {\n    .brand-link {\n      height: $main-header-height;\n      width: $sidebar-mini-width;\n\n      &.text-sm {\n        height: $main-header-height-sm;\n      }\n    }\n  }\n\n  .layout-navbar-fixed.sidebar-mini.sidebar-collapse.text-sm &,\n  .layout-navbar-fixed.sidebar-mini-md.sidebar-collapse.text-sm &,\n  .layout-navbar-fixed.sidebar-mini-xs.sidebar-collapse.text-sm & {\n    .brand-link {\n      height: $main-header-height-sm;\n    }\n  }\n\n  body:not(.layout-fixed).layout-navbar-fixed & {\n    .main-sidebar {\n      // margin-top: calc(#{$main-header-height} / -1);\n\n      // .sidebar {\n      //   margin-top: $main-header-height;\n      // }\n    }\n  }\n\n  body:not(.layout-fixed).layout-navbar-fixed.text-sm & {\n    .main-sidebar {\n      margin-top: calc(#{$main-header-height-sm} / -1);\n\n      .sidebar {\n        margin-top: $main-header-height-sm;\n      }\n    }\n  }\n\n  .layout-navbar-fixed & {\n    .control-sidebar {\n      top: 0;\n    }\n\n    a.anchor {\n      display: block;\n      position: relative;\n      top: calc((#{$main-header-height-inner} + #{$main-header-bottom-border-width} + (#{$main-header-link-padding-y} * 2)) / -1);\n    }\n\n    .main-sidebar:hover {\n      .brand-link {\n        transition: width $transition-speed $transition-fn;\n        width: $sidebar-width;\n      }\n    }\n\n    .brand-link {\n      overflow: hidden;\n      position: fixed;\n      top: 0;\n      transition: width $transition-speed $transition-fn;\n      width: $sidebar-width;\n      z-index: $zindex-main-header + 1;\n    }\n\n    // Sidebar variants brand-link fix\n    @each $name, $color in $theme-colors {\n      .sidebar-dark-#{$name} .brand-link:not([class*=\"navbar\"]) {\n        background-color: $sidebar-dark-bg;\n      }\n\n      .sidebar-light-#{$name} .brand-link:not([class*=\"navbar\"]) {\n        background-color: $sidebar-light-bg;\n      }\n    }\n\n    @each $name, $color in $colors {\n      .sidebar-dark-#{$name} .brand-link:not([class*=\"navbar\"]) {\n        background-color: $sidebar-dark-bg;\n      }\n\n      .sidebar-light-#{$name} .brand-link:not([class*=\"navbar\"]) {\n        background-color: $sidebar-light-bg;\n      }\n    }\n\n    .main-header.border-bottom-0 ~ .content-wrapper {\n      margin-top: $main-header-height-inner;\n    }\n    .content-wrapper {\n      margin-top: $main-header-height;\n    }\n\n    .main-header.text-sm ~ .content-wrapper {\n      margin-top: $main-header-height-sm;\n    }\n\n    .main-header {\n      left: 0;\n      position: fixed;\n      right: 0;\n      top: 0;\n      z-index: $zindex-main-header - 1;\n    }\n  }\n\n  .layout-navbar-fixed.text-sm & {\n    .content-wrapper {\n      margin-top: $main-header-height-sm;\n    }\n  }\n\n  .layout-navbar-not-fixed & {\n    .brand-link {\n      position: static;\n    }\n\n    .sidebar,\n    .content-wrapper {\n      margin-top: 0;\n    }\n\n    .main-header {\n      position: static;\n    }\n  }\n\n  .layout-navbar-not-fixed.layout-fixed & {\n    .sidebar {\n      margin-top: 0;\n    }\n  }\n\n  @each $breakpoint in map-keys($grid-breakpoints) {\n    @include media-breakpoint-up($breakpoint) {\n      $infix: breakpoint-infix($breakpoint, $grid-breakpoints);\n\n      .layout#{$infix}-navbar-fixed.layout-fixed & {\n        .control-sidebar {\n          top: $main-header-height;\n        }\n\n        .text-sm & .main-header ~ .control-sidebar,\n        .main-header.text-sm ~ .control-sidebar {\n          top: $main-header-height-sm;\n        }\n\n        .sidebar {\n          margin-top: $main-header-height;\n        }\n\n        .text-sm & .brand-link ~ .sidebar,\n        .brand-link.text-sm ~ .sidebar {\n          margin-top: $main-header-height-sm;\n        }\n      }\n\n      .layout#{$infix}-navbar-fixed.layout-fixed.text-sm & {\n        .control-sidebar {\n          top: $main-header-height-sm;\n        }\n\n        .sidebar {\n          margin-top: $main-header-height-sm;\n        }\n      }\n\n      .layout#{$infix}-navbar-fixed & {\n        .control-sidebar {\n          top: 0;\n        }\n\n        a.anchor {\n          display: block;\n          position: relative;\n          top: calc((#{$main-header-height-inner} + #{$main-header-bottom-border-width} + (#{$main-header-link-padding-y} * 2)) / -1);\n        }\n\n        &.sidebar-collapse {\n          .brand-link {\n            height: $main-header-height;\n            transition: width $transition-speed $transition-fn;\n            width: $sidebar-mini-width;\n\n            .text-sm &,\n            &.text-sm {\n              height: $main-header-height-sm;\n            }\n          }\n\n          .main-sidebar:hover {\n            .brand-link {\n              transition: width $transition-speed $transition-fn;\n              width: $sidebar-width;\n            }\n          }\n        }\n\n        .brand-link {\n          overflow: hidden;\n          position: fixed;\n          top: 0;\n          transition: width $transition-speed $transition-fn;\n          width: $sidebar-width;\n          z-index: $zindex-main-header + 1;\n        }\n\n        .content-wrapper {\n          margin-top: $main-header-height;\n        }\n\n        .text-sm & .main-header ~ .content-wrapper,\n        .main-header.text-sm ~ .content-wrapper {\n          margin-top: $main-header-height-sm;\n        }\n\n        .main-header {\n          left: 0;\n          position: fixed;\n          right: 0;\n          top: 0;\n          z-index: $zindex-main-sidebar - 1;\n        }\n      }\n\n      .layout#{$infix}-navbar-fixed.text-sm & {\n        .content-wrapper {\n          margin-top: $main-header-height-sm;\n        }\n      }\n\n      body:not(.layout-fixed).layout#{$infix}-navbar-fixed & {\n        // .main-sidebar {\n        //   margin-top: calc(#{$main-header-height} / -1);\n\n        //   .sidebar {\n        //     margin-top: $main-header-height;\n        //   }\n        // }\n      }\n\n      body:not(.layout-fixed).layout#{$infix}-navbar-fixed.text-sm & {\n        .main-sidebar {\n          margin-top: calc(#{$main-header-height-sm} / -1);\n\n          .sidebar {\n            margin-top: $main-header-height-sm;\n          }\n        }\n      }\n\n      .layout#{$infix}-navbar-not-fixed & {\n        .brand-link {\n          position: static;\n        }\n\n        .sidebar,\n        .content-wrapper {\n          margin-top: 0;\n        }\n\n        .main-header {\n          position: static;\n        }\n      }\n\n      .layout#{$infix}-navbar-not-fixed.layout-fixed & {\n        .sidebar {\n          margin-top: 0;\n        }\n      }\n    }\n  }\n\n  .layout-footer-fixed & {\n    .control-sidebar {\n      bottom: 0;\n    }\n\n    .main-footer {\n      bottom: 0;\n      left: 0;\n      position: fixed;\n      right: 0;\n      z-index: $zindex-main-footer;\n    }\n  }\n\n  .layout-footer-not-fixed & {\n    .main-footer {\n      position: static;\n    }\n\n    .content-wrapper {\n      margin-bottom: 0;\n    }\n  }\n\n  @each $breakpoint in map-keys($grid-breakpoints) {\n    @include media-breakpoint-up($breakpoint) {\n      $infix: breakpoint-infix($breakpoint, $grid-breakpoints);\n      .layout#{$infix}-footer-fixed & {\n        .control-sidebar {\n          bottom: 0;\n        }\n\n        .main-footer {\n          bottom: 0;\n          left: 0;\n          position: fixed;\n          right: 0;\n          z-index: $zindex-main-footer;\n        }\n\n        .content-wrapper {\n          padding-bottom: $main-footer-height;\n        }\n      }\n\n      .layout#{$infix}-footer-not-fixed & {\n        .main-footer {\n          position: static;\n        }\n      }\n    }\n  }\n\n  .layout-top-nav & {\n    margin-left: 0;\n\n    .main-header {\n      .brand-image {\n        margin-top: -.5rem;\n        margin-right: .2rem;\n        height: 33px;\n      }\n    }\n\n    .main-sidebar {\n      bottom: inherit;\n      height: inherit;\n    }\n\n    .content-wrapper,\n    .main-header,\n    .main-footer {\n      margin-left: 0;\n    }\n  }\n}\n\n\nbody.sidebar-collapse:not(.sidebar-mini-xs):not(.sidebar-mini-md):not(.sidebar-mini) {\n  .content-wrapper,\n  .main-footer,\n  .main-header {\n    &,\n    &::before {\n      margin-left: 0;\n    }\n  }\n}\n\nbody:not(.sidebar-mini-md):not(.sidebar-mini-xs):not(.layout-top-nav) {\n  .content-wrapper,\n  .main-footer,\n  .main-header {\n    @include media-breakpoint-up(md) {\n      @include transition(margin-left $transition-speed $transition-fn);\n\n      margin-left: $sidebar-width;\n\n      .sidebar-collapse & {\n        margin-left: 0;\n      }\n    }\n\n    @include media-breakpoint-down(md) {\n      margin-left: 0;\n    }\n  }\n}\n\n.sidebar-mini-md {\n  .content-wrapper,\n  .main-footer,\n  .main-header {\n    @include media-breakpoint-up(md) {\n      @include transition(margin-left $transition-speed $transition-fn);\n\n      margin-left: $sidebar-width;\n\n      .sidebar-collapse & {\n        margin-left: $sidebar-mini-width;\n      }\n    }\n    @include media-breakpoint-down(md) {\n      margin-left: $sidebar-mini-width;\n    }\n    @include media-breakpoint-down(sm) {\n      margin-left: 0;\n    }\n  }\n}\n\n.sidebar-mini-xs {\n  .content-wrapper,\n  .main-footer,\n  .main-header {\n    @include media-breakpoint-up(md) {\n      @include transition(margin-left $transition-speed $transition-fn);\n\n      margin-left: $sidebar-width;\n\n      .sidebar-collapse & {\n        margin-left: $sidebar-mini-width;\n      }\n    }\n    @include media-breakpoint-down(md) {\n      margin-left: $sidebar-mini-width;\n    }\n  }\n}\n\n.content-wrapper {\n  background-color: $main-bg;\n\n  > .content {\n    padding: $content-padding-y $content-padding-x;\n  }\n}\n\n.main-sidebar {\n  &,\n  &::before {\n    $local-sidebar-transition: margin-left $transition-speed $transition-fn, width $transition-speed $transition-fn;\n    @include transition($local-sidebar-transition);\n    width: $sidebar-width;\n  }\n\n  .sidebar-collapse:not(.sidebar-mini):not(.sidebar-mini-md):not(.sidebar-mini-xs) & {\n    &,\n    &::before {\n      box-shadow: none !important;\n    }\n  }\n\n  .sidebar-collapse & {\n    &,\n    &::before {\n      margin-left: -$sidebar-width;\n    }\n\n    .nav-sidebar.nav-child-indent .nav-treeview {\n      padding: 0;\n    }\n  }\n\n  @include media-breakpoint-down(sm) {\n    &,\n    &::before {\n      box-shadow: none !important;\n      margin-left: -$sidebar-width;\n    }\n\n    .sidebar-open & {\n      &,\n      &::before {\n        margin-left: 0;\n      }\n    }\n  }\n}\n\nbody:not(.layout-fixed) {\n  .main-sidebar {\n    height: inherit;\n    min-height: 100%;\n    position: absolute;\n    top: 0;\n\n    .sidebar {\n      overflow-y: auto;\n    }\n  }\n}\n\n.layout-fixed {\n  .brand-link {\n    width: $sidebar-width;\n  }\n\n  .main-sidebar {\n    bottom: 0;\n    float: none;\n    left: 0;\n    position: fixed;\n    top: 0;\n  }\n\n  .control-sidebar {\n    bottom: 0;\n    float: none;\n    position: fixed;\n    top: 0;\n\n    .control-sidebar-content {\n      height: calc(100vh - #{$main-header-height});\n      overflow-y: auto;\n      @include scrollbar-width-thin();\n      @include scrollbar-color-gray();\n    }\n  }\n}\n\n@supports (-webkit-touch-callout: none) {\n  .layout-fixed {\n    .main-sidebar {\n      height: inherit;\n    }\n  }\n}\n\n.main-footer {\n  background-color: $main-footer-bg;\n  border-top: $main-footer-border-top;\n  color: lighten($gray-700, 25%);\n  padding: $main-footer-padding;\n\n  .text-sm &,\n  &.text-sm {\n    padding: $main-footer-padding-sm;\n  }\n}\n\n.content-header {\n  padding: 15px $content-padding-x;\n\n  .text-sm & {\n    padding: 10px $content-padding-x;\n  }\n\n  h1 {\n    font-size: 1.8rem;\n    margin: 0;\n\n    .text-sm & {\n      font-size: 1.5rem;\n    }\n  }\n\n  .breadcrumb {\n    background-color: transparent;\n    line-height: 1.8rem;\n    margin-bottom: 0;\n    padding: 0;\n\n    .text-sm & {\n      line-height: 1.5rem;\n    }\n  }\n}\n\n\n.hold-transition {\n  .content-wrapper,\n  .main-header,\n  .main-sidebar,\n  .main-sidebar *,\n  .control-sidebar,\n  .control-sidebar *,\n  .main-footer {\n    transition: none !important;\n    animation-duration: 0s !important;\n  }\n}\n\n@include dark-mode () {\n  background-color: $dark-main-bg;\n  color: $white;\n\n  .wrapper {\n    .layout-navbar-fixed & {\n      @each $name, $color in $theme-colors-alt {\n        .sidebar-dark-#{$name} .brand-link:not([class*=\"navbar\"]) {\n          background-color: $sidebar-dark-bg;\n        }\n\n        .sidebar-light-#{$name} .brand-link:not([class*=\"navbar\"]) {\n          background-color: $sidebar-light-bg;\n        }\n      }\n    }\n\n    @each $breakpoint in map-keys($grid-breakpoints) {\n      @include media-breakpoint-up($breakpoint) {\n        $infix: breakpoint-infix($breakpoint, $grid-breakpoints);\n\n        .layout#{$infix}-navbar-fixed & {\n          @each $name, $color in $theme-colors-alt {\n            .sidebar-dark-#{$name} .brand-link:not([class*=\"navbar\"]) {\n              background-color: $sidebar-dark-bg;\n            }\n\n            .sidebar-light-#{$name} .brand-link:not([class*=\"navbar\"]) {\n              background-color: $sidebar-light-bg;\n            }\n          }\n        }\n      }\n    }\n  }\n\n  .breadcrumb-item {\n    &.active,\n    + .breadcrumb-item::before {\n      color: $gray-500;\n    }\n  }\n  .main-footer {\n    background-color: $dark;\n    border-color: lighten($dark, 10%);\n  }\n  .content-wrapper {\n    background-color: lighten($dark, 7.5%);\n    color: $white;\n\n    .content-header {\n      color: $white;\n    }\n  }\n}\n","//\n// Mixins: Scrollbar\n//\n\n@mixin scrollbar-color-gray() {\n  scrollbar-color: #a9a9a9 transparent;\n\n  &::-webkit-scrollbar-thumb {\n    background-color: #a9a9a9;\n  }\n\n  &::-webkit-scrollbar-track {\n    background-color: transparent;\n  }\n\n  &::-webkit-scrollbar-corner {\n    background-color: transparent;\n  }\n}\n\n@mixin scrollbar-width-thin() {\n  scrollbar-width: thin;\n\n  &::-webkit-scrollbar {\n    width: .5rem;\n    height: .5rem;\n  }\n}\n\n@mixin scrollbar-width-none() {\n  scrollbar-width: none;\n\n  &::-webkit-scrollbar {\n    width: 0;\n  }\n}\n\n//\n","//\n// Component: Main Header\n//\n\n.main-header {\n  border-bottom: $main-header-bottom-border;\n  z-index: $zindex-main-header;\n\n  .nav-link {\n    height: $nav-link-height;\n    position: relative;\n  }\n\n  .text-sm &,\n  &.text-sm {\n    .nav-link {\n      height: $nav-link-sm-height;\n      padding: $nav-link-sm-padding-y $nav-link-padding-x;\n\n      > .fa,\n      > .fas,\n      > .far,\n      > .fab,\n      > .fal,\n      > .fad,\n      > .svg-inline--fa,\n      > .ion {\n        font-size: $font-size-sm;\n      }\n    }\n\n  }\n\n  .navbar-nav {\n    .nav-item {\n      margin: 0;\n    }\n\n    &[class*=\"-right\"] {\n      .dropdown-menu {\n        left: auto;\n        margin-top: -3px;\n        right: 0;\n\n        @media (max-width: breakpoint-max(xs)) {\n          left: 0;\n          right: auto;\n        }\n      }\n    }\n  }\n\n  &.dropdown-legacy .dropdown-menu {\n    top: $nav-link-height + $navbar-padding-y;\n    margin-top: 0;\n  }\n}\n\n// Add this class to images within a nav-link\n.navbar-img {\n  height: calc(#{$main-header-height} * .5);\n  width: auto;\n}\n\n// Navbar badge\n.navbar-badge {\n  font-size: .6rem;\n  font-weight: 300;\n  padding: 2px 4px;\n  position: absolute;\n  right: 5px;\n  top: 9px;\n}\n\n.btn-navbar {\n  background-color: transparent;\n  border-left-width: 0;\n}\n\n.form-control-navbar {\n  border-right-width: 0;\n\n  + .input-group-append {\n    margin-left: 0;\n  }\n}\n\n.form-control-navbar,\n.btn-navbar {\n  transition: none;\n}\n\n.navbar-dark {\n  .form-control-navbar,\n  .btn-navbar {\n    background-color: $main-header-dark-form-control-bg;\n    border-color: $main-header-dark-form-control-border-color;\n  }\n\n  .form-control-navbar {\n    &::placeholder {\n      color: $main-header-dark-placeholder-color;\n    }\n\n    + .input-group-append > .btn-navbar {\n      color: $main-header-dark-placeholder-color;\n    }\n\n    &:focus {\n      &,\n      + .input-group-append .btn-navbar {\n        background-color: $main-header-dark-form-control-focused-bg;\n        border-color: $main-header-dark-form-control-focused-border-color !important;\n        color: $main-header-dark-form-control-focused-color;\n      }\n    }\n  }\n}\n\n.navbar-light {\n  .form-control-navbar,\n  .btn-navbar {\n    background-color: $main-header-light-form-control-bg;\n    border-color: $main-header-light-form-control-border-color;\n  }\n\n  .form-control-navbar {\n    &::placeholder {\n      color: $main-header-light-placeholder-color;\n    }\n\n    + .input-group-append > .btn-navbar {\n      color: $main-header-light-placeholder-color;\n    }\n\n    &:focus {\n      &,\n      + .input-group-append .btn-navbar {\n        background-color: $main-header-light-form-control-focused-bg;\n        border-color: $main-header-light-form-control-focused-border-color !important;\n        color: $main-header-light-form-control-focused-color;\n      }\n    }\n  }\n\n  .navbar-search-block {\n    .form-control-navbar {\n      &:focus {\n        &,\n        + .input-group-append .btn-navbar {\n          color: $main-header-light-placeholder-color;\n        }\n      }\n    }\n  }\n}\n\n// Navbar Search\n.navbar-search-block {\n  position: absolute;\n  padding: 0 $nav-link-padding-x;\n  left: 0;\n  top: 0;\n  right: 0;\n  bottom: 0;\n  z-index: 10;\n  display: none;\n  justify-content: center;\n  flex-direction: column;\n  background-color: initial;\n\n  &.navbar-search-open {\n    display: flex;\n  }\n\n  .input-group {\n    width: 100%;\n  }\n}\n","//\n// Component: Brand\n//\n\n.brand-link {\n  $brand-link-padding-y: $navbar-brand-padding-y + $navbar-padding-y;\n  display: block;\n  font-size: $navbar-brand-font-size;\n  line-height: $line-height-lg;\n  padding: $brand-link-padding-y $sidebar-padding-x;\n  transition: width $transition-speed $transition-fn;\n  white-space: nowrap;\n\n  &:hover {\n    color: $white;\n    text-decoration: none;\n  }\n\n  .text-sm & {\n    font-size: inherit;\n  }\n\n  [class*=\"sidebar-dark\"] & {\n    border-bottom: 1px solid lighten($dark, 10%);\n\n    &,\n    .pushmenu {\n      color: rgba($white, .8);\n\n      &:hover {\n        color: $white;\n      }\n    }\n  }\n\n  [class*=\"sidebar-light\"] & {\n    border-bottom: 1px solid $gray-300;\n\n    &,\n    .pushmenu {\n      color: rgba($black, .8);\n\n      &:hover {\n        color: $black;\n      }\n    }\n  }\n\n  .pushmenu {\n    margin-right: $sidebar-padding-x;\n    font-size: $font-size-base;\n  }\n\n  .brand-link {\n    padding: 0;\n    border-bottom: none;\n  }\n\n  .brand-image {\n    float: left;\n    line-height: .8;\n    margin-left: .8rem;\n    margin-right: .5rem;\n    margin-top: -3px;\n    max-height: 33px;\n    width: auto;\n  }\n\n  .brand-image-xs {\n    float: left;\n    line-height: .8;\n    margin-top: -.1rem;\n    max-height: 33px;\n    width: auto;\n  }\n\n  .brand-image-xl {\n    line-height: .8;\n    max-height: 40px;\n    width: auto;\n\n    &.single {\n      margin-top: -.3rem;\n    }\n  }\n\n  &.text-sm,\n  .text-sm & {\n    .brand-image {\n      height: 29px;\n      margin-bottom: -.25rem;\n      margin-left: .95rem;\n      margin-top: -.25rem;\n    }\n\n    .brand-image-xs {\n      margin-top: -.2rem;\n      max-height: 29px;\n    }\n\n    .brand-image-xl {\n      margin-top: -.225rem;\n      max-height: 38px;\n    }\n  }\n}\n","//\n// Component: Main Sidebar\n//\n\n.main-sidebar {\n  height: 100vh;\n  overflow-y: hidden;\n  z-index: $zindex-main-sidebar;\n\n  // Remove Firefox Focusring\n  a {\n    &:-moz-focusring {\n      border: 0;\n      outline: none;\n    }\n  }\n}\n\n.sidebar {\n  height: calc(100% - (#{$main-header-height-inner} + #{$main-header-bottom-border-width}));\n  overflow-x: hidden;\n  overflow-y: initial;\n  padding-bottom: $sidebar-padding-y;\n  padding-left: $sidebar-padding-x;\n  padding-right: $sidebar-padding-x;\n  padding-top: $sidebar-padding-y;\n  @include scrollbar-color-gray();\n  @include scrollbar-width-none();\n\n  &:hover {\n    @include scrollbar-width-thin();\n  }\n\n  .brand-link.border-bottom-0 ~ & {\n    height: calc(100% - #{$main-header-height-inner});\n  }\n}\n\n// Sidebar user panel\n.user-panel {\n  position: relative;\n\n  [class*=\"sidebar-dark\"] & {\n    border-bottom: 1px solid lighten($dark, 12%);\n  }\n\n  [class*=\"sidebar-light\"] & {\n    border-bottom: 1px solid $gray-300;\n  }\n\n  &,\n  .info {\n    overflow: hidden;\n    white-space: nowrap;\n  }\n\n  .image {\n    display: inline-block;\n    padding-left: $nav-link-padding-x - .2;\n  }\n\n  img {\n    height: auto;\n    width: $sidebar-user-image-width;\n  }\n\n  .info {\n    display: inline-block;\n    padding: 5px 5px 5px 10px;\n  }\n\n  .status,\n  .dropdown-menu {\n    font-size: $font-size-sm;\n  }\n}\n\n// Sidebar navigation menu\n.nav-sidebar {\n  // All levels\n  .nav-item {\n    > .nav-link {\n      margin-bottom: .2rem;\n\n      .right {\n        @include transition(transform $transition-fn $transition-speed);\n      }\n    }\n  }\n\n  .nav-link > .right,\n  .nav-link > p > .right {\n    position: absolute;\n    right: 1rem;\n    top: .7rem;\n\n    i,\n    span {\n      margin-left: .5rem;\n    }\n\n    &:nth-child(2) {\n      right: 2.2rem;\n    }\n  }\n\n  .menu-open {\n    > .nav-treeview {\n      display: block;\n    }\n  }\n\n  .menu-open,\n  .menu-is-opening {\n    > .nav-link {\n      svg.right,\n      i.right {\n        @include rotate(-90deg);\n      }\n    }\n  }\n\n  // First Level\n  > .nav-item {\n    margin-bottom: 0;\n\n    .nav-icon {\n      margin-left: .05rem;\n      font-size: 1.2rem;\n      margin-right: .2rem;\n      text-align: center;\n      width: $sidebar-nav-icon-width;\n\n      &.fa,\n      &.fas,\n      &.far,\n      &.fab,\n      &.fal,\n      &.fad,\n      &.svg-inline--fa,\n      &.ion {\n        font-size: 1.1rem;\n      }\n    }\n\n    .float-right {\n      margin-top: 3px;\n    }\n  }\n\n  // Tree view menu\n  .nav-treeview {\n    display: none;\n    list-style: none;\n    padding: 0;\n\n    > .nav-item {\n      > .nav-link {\n        > .nav-icon {\n          width: $sidebar-nav-icon-width;\n        }\n      }\n    }\n  }\n\n  &.nav-child-indent {\n    .nav-treeview {\n      transition: padding $transition-speed $transition-fn;\n      padding-left: 1rem;\n\n      .text-sm & {\n        padding-left: .5rem;\n      }\n    }\n\n    &.nav-legacy {\n      .nav-treeview {\n        .nav-treeview {\n          padding-left: 2rem;\n          margin-left: -1rem;\n\n          .text-sm & {\n            padding-left: 1rem;\n            margin-left: -.5rem;\n          }\n        }\n      }\n    }\n  }\n\n  .nav-header {\n    font-size: .9rem;\n    padding: $nav-link-padding-y ($nav-link-padding-y * 1.5);\n  }\n\n  .nav-link p {\n    display: inline;\n    margin: 0;\n    white-space: normal;\n  }\n}\n\n.sidebar-is-opening .sidebar .nav-sidebar {\n  .nav-link p {\n    animation-name: fadeIn;\n    animation-duration: $transition-speed;\n    animation-fill-mode: both;\n  }\n}\n\n#sidebar-overlay {\n  @include media-breakpoint-down(md) {\n    .sidebar-open & {\n      display: block;\n    }\n  }\n\n  background-color: rgba($black, .1);\n  bottom: 0;\n  display: none;\n  left: 0;\n  position: fixed;\n  right: 0;\n  top: 0;\n  z-index: $zindex-main-sidebar - 1;\n}\n\n[class*=\"sidebar-light-\"] {\n  // Sidebar background color\n  background-color: $sidebar-light-bg;\n\n  // User Panel (resides in the sidebar)\n  .user-panel {\n    a:hover {\n      color: $sidebar-light-hover-color;\n    }\n\n    .status {\n      background-color: $sidebar-light-hover-bg;\n      color: $sidebar-light-color;\n\n      &:hover,\n      &:focus,\n      &:active {\n        background-color: darken($sidebar-light-hover-bg, 3%);\n        color: $sidebar-light-hover-color;\n      }\n    }\n\n    .dropdown-menu {\n      @include box-shadow(0 2px 4px rgba(0, 0, 0, .4));\n      border-color: darken($sidebar-light-hover-bg, 5%);\n    }\n\n    .dropdown-item {\n      color: $body-color;\n    }\n  }\n\n  // Sidebar Menu. First level links\n  .nav-sidebar > .nav-item {\n    // links\n    > .nav-link {\n      // border-left: 3px solid transparent;\n      &:active,\n      &:focus {\n        color: $sidebar-light-color;\n      }\n    }\n\n    // Hover and active states\n    &.menu-open > .nav-link,\n    &:hover > .nav-link {\n      background-color: $sidebar-light-hover-bg;\n      color: $sidebar-light-hover-color;\n    }\n\n    > .nav-link.active {\n      color: $sidebar-light-active-color;\n\n      @if $enable-shadows {\n        box-shadow: map-get($elevations, 1);\n      }\n    }\n\n    // First Level Submenu\n    > .nav-treeview {\n      background-color: $sidebar-light-submenu-bg;\n    }\n  }\n\n  // Section Heading\n  .nav-header {\n    background-color: inherit;\n    color: darken($sidebar-light-color, 5%);\n  }\n\n  // All links within the sidebar menu\n  .sidebar {\n    a {\n      color: $sidebar-light-color;\n\n      &:hover {\n        text-decoration: none;\n      }\n    }\n  }\n\n  // All submenus\n  .nav-treeview {\n    > .nav-item {\n      > .nav-link {\n        color: $sidebar-light-submenu-color;\n\n        &:hover,\n        &:focus {\n          background-color: $sidebar-light-submenu-hover-bg;\n          color: $sidebar-light-submenu-hover-color;\n        }\n      }\n\n      > .nav-link.active {\n        &,\n        &:hover {\n          background-color: $sidebar-light-submenu-active-bg;\n          color: $sidebar-light-submenu-active-color;\n        }\n      }\n\n      > .nav-link:hover {\n        background-color: $sidebar-light-submenu-hover-bg;\n      }\n    }\n  }\n\n  // Flat style\n  .nav-flat {\n    .nav-item {\n      .nav-treeview {\n        .nav-treeview {\n          border-color: $sidebar-light-submenu-active-bg;\n        }\n\n        > .nav-item {\n          > .nav-link {\n            &,\n            &.active {\n              border-color: $sidebar-light-submenu-active-bg;\n            }\n          }\n        }\n      }\n    }\n  }\n}\n\n[class*=\"sidebar-dark-\"] {\n  // Sidebar background color\n  background-color: $sidebar-dark-bg;\n\n  // User Panel (resides in the sidebar)\n  .user-panel {\n    a:hover {\n      color: $sidebar-dark-hover-color;\n    }\n\n    .status {\n      background-color: $sidebar-dark-hover-bg;\n      color: $sidebar-dark-color;\n\n      &:hover,\n      &:focus,\n      &:active {\n        background-color: darken($sidebar-dark-hover-bg, 3%);\n        color: $sidebar-dark-hover-color;\n      }\n    }\n\n    .dropdown-menu {\n      @include box-shadow(0 2px 4px rgba(0, 0, 0, .4));\n      border-color: darken($sidebar-dark-hover-bg, 5%);\n    }\n\n    .dropdown-item {\n      color: $body-color;\n    }\n  }\n\n  // Sidebar Menu. First level links\n  .nav-sidebar > .nav-item {\n    // links\n    > .nav-link {\n      // border-left: 3px solid transparent;\n      &:active {\n        color: $sidebar-dark-color;\n      }\n    }\n\n    // Hover and active states\n    &.menu-open > .nav-link,\n    &:hover > .nav-link,\n    > .nav-link:focus {\n      background-color: $sidebar-dark-hover-bg;\n      color: $sidebar-dark-hover-color;\n    }\n\n    > .nav-link.active {\n      color: $sidebar-dark-hover-color;\n\n      @if $enable-shadows {\n        box-shadow: map-get($elevations, 1);\n      }\n    }\n\n    // First Level Submenu\n    > .nav-treeview {\n      background-color: $sidebar-dark-submenu-bg;\n    }\n  }\n\n  // Section Heading\n  .nav-header {\n    background-color: inherit; //darken($sidebar-dark-bg, 3%);\n    color: lighten($sidebar-dark-color, 5%);\n  }\n\n  // All links within the sidebar menu\n  .sidebar {\n    a {\n      color: $sidebar-dark-color;\n\n      &:hover,\n      &:focus {\n        text-decoration: none;\n      }\n    }\n  }\n\n  // All submenus\n  .nav-treeview {\n    > .nav-item {\n      > .nav-link {\n        color: $sidebar-dark-submenu-color;\n\n        &:hover,\n        &:focus {\n          background-color: $sidebar-dark-submenu-hover-bg;\n          color: $sidebar-dark-submenu-hover-color;\n        }\n      }\n\n      > .nav-link.active {\n        &,\n        &:hover,\n        &:focus {\n          background-color: $sidebar-dark-submenu-active-bg;\n          color: $sidebar-dark-submenu-active-color;\n        }\n      }\n    }\n  }\n\n  // Flat Style\n  .nav-flat {\n    .nav-item {\n      .nav-treeview {\n        .nav-treeview {\n          border-color: $sidebar-dark-submenu-active-bg;\n        }\n\n        > .nav-item {\n          > .nav-link {\n            &,\n            &.active {\n              border-color: $sidebar-dark-submenu-active-bg;\n            }\n          }\n        }\n      }\n    }\n  }\n}\n\n// Sidebar variants\n@each $name, $color in $theme-colors {\n  .sidebar-dark-#{$name},\n  .sidebar-light-#{$name} {\n    @include sidebar-color($color);\n  }\n}\n\n@each $name, $color in $colors {\n  .sidebar-dark-#{$name},\n  .sidebar-light-#{$name} {\n    @include sidebar-color($color);\n  }\n}\n\n.sidebar-mini .main-sidebar:not(.sidebar-no-expand),\n.sidebar-mini-md .main-sidebar:not(.sidebar-no-expand),\n.sidebar-mini-xs .main-sidebar:not(.sidebar-no-expand),\n.sidebar-mini .main-sidebar:not(.sidebar-no-expand):hover,\n.sidebar-mini-md .main-sidebar:not(.sidebar-no-expand):hover,\n.sidebar-mini-xs .main-sidebar:not(.sidebar-no-expand):hover,\n.sidebar-mini .main-sidebar.sidebar-focused,\n.sidebar-mini-md .main-sidebar.sidebar-focused,\n.sidebar-mini-xs .main-sidebar.sidebar-focused {\n  .nav-compact.nav-sidebar.nav-child-indent:not(.nav-flat) .nav-treeview {\n    padding-left: 1rem;\n    margin-left: -.5rem;\n  }\n}\n\n// Nav Flat\n.nav-flat {\n  margin: (-$sidebar-padding-x * .5) (-$sidebar-padding-x) 0;\n\n  .nav-item {\n    > .nav-link {\n      border-radius: 0;\n      margin-bottom: 0;\n\n      > .nav-icon {\n        margin-left: .55rem;\n      }\n    }\n  }\n\n  &:not(.nav-child-indent) {\n    .nav-treeview {\n      .nav-item {\n        > .nav-link {\n          > .nav-icon {\n            margin-left: .4rem;\n          }\n        }\n      }\n    }\n  }\n\n  &.nav-child-indent {\n    .nav-treeview {\n      padding-left: 0;\n\n      .nav-icon {\n        margin-left: .85rem;\n      }\n\n      .nav-treeview {\n        border-left: .2rem solid;\n\n        .nav-icon {\n          margin-left: 1.15rem;\n        }\n\n        .nav-treeview {\n          .nav-icon {\n            margin-left: 1.45rem;\n          }\n\n          .nav-treeview {\n            .nav-icon {\n              margin-left: 1.75rem;\n            }\n\n            .nav-treeview {\n              .nav-icon {\n                margin-left: 2.05rem;\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n\n  .sidebar-collapse &.nav-child-indent .sidebar {\n    .nav-treeview {\n      .nav-icon {\n        margin-left: .55rem;\n      }\n\n      .nav-link {\n        padding-left: calc(#{$nav-link-padding-x} - .2rem);\n      }\n\n      .nav-treeview {\n        .nav-icon {\n          margin-left: .35rem;\n        }\n\n        .nav-treeview {\n          .nav-icon {\n            margin-left: .15rem;\n          }\n\n          .nav-treeview {\n            .nav-icon {\n              margin-left: -.15rem;\n            }\n\n            .nav-treeview {\n              .nav-icon {\n                margin-left: -.35rem;\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n\n  .sidebar-mini .main-sidebar:not(.sidebar-no-expand):hover &,\n  .sidebar-mini-md .main-sidebar:not(.sidebar-no-expand):hover &,\n  .sidebar-mini-xs .main-sidebar:not(.sidebar-no-expand):hover &,\n  .sidebar-mini .main-sidebar.sidebar-focused &,\n  .sidebar-mini-md .main-sidebar.sidebar-focused &,\n  .sidebar-mini-xs .main-sidebar.sidebar-focused & {\n    &.nav-compact.nav-sidebar .nav-treeview {\n      .nav-icon {\n        margin-left: .4rem;\n      }\n    }\n\n    &.nav-sidebar.nav-child-indent .nav-treeview {\n      .nav-icon {\n        margin-left: .85rem;\n      }\n\n      .nav-treeview {\n        .nav-icon {\n          margin-left: 1.15rem;\n        }\n\n        .nav-treeview {\n          .nav-icon {\n            margin-left: 1.45rem;\n          }\n\n          .nav-treeview {\n            .nav-icon {\n              margin-left: 1.75rem;\n            }\n\n            .nav-treeview {\n              .nav-icon {\n                margin-left: 2.05rem;\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n\n  .nav-icon {\n    @include transition(margin-left $transition-fn $transition-speed);\n  }\n\n  .nav-treeview {\n    .nav-icon {\n      margin-left: -.2rem;\n    }\n  }\n\n  &.nav-sidebar > .nav-item {\n    .nav-treeview,\n    > .nav-treeview {\n      background-color: rgba($white, .05);\n\n      .nav-item {\n        > .nav-link {\n          border-left: .2rem solid;\n        }\n      }\n    }\n  }\n}\n\n.nav-legacy {\n  margin: (-$sidebar-padding-x * .5) (-$sidebar-padding-x) 0;\n\n  &.nav-sidebar .nav-item {\n    > .nav-link {\n      border-radius: 0;\n      margin-bottom: 0;\n\n      > .nav-icon {\n        margin-left: .55rem;\n\n        .text-sm & {\n          margin-left: .75rem;\n        }\n      }\n    }\n  }\n\n  &.nav-sidebar > .nav-item {\n    > .nav-link {\n      &.active {\n        background-color: inherit;\n        border-left: 3px solid transparent;\n        box-shadow: none;\n\n        > .nav-icon {\n          margin-left: calc(.55rem - 3px);\n\n          .text-sm & {\n            margin-left: calc(.75rem - 3px);\n          }\n        }\n      }\n    }\n  }\n\n  .text-sm &.nav-sidebar.nav-flat .nav-treeview {\n    .nav-item {\n      > .nav-link {\n        > .nav-icon {\n          margin-left: calc(.75rem - 3px);\n        }\n      }\n    }\n  }\n\n  .sidebar-mini &,\n  .sidebar-mini-md &,\n  .sidebar-mini-xs & {\n    > .nav-item .nav-link {\n      .nav-icon {\n        @include transition(margin-left $transition-fn $transition-speed);\n        margin-left: .6rem;\n      }\n    }\n  }\n\n  .sidebar-mini.sidebar-collapse,\n  .sidebar-mini-md.sidebar-collapse,\n  .sidebar-mini-xs.sidebar-collapse {\n    .main-sidebar.sidebar-focused &.nav-child-indent,\n    .main-sidebar:hover &.nav-child-indent {\n      .nav-treeview {\n        padding-left: 1rem;\n\n        .nav-treeview {\n          padding-left: 2rem;\n          margin-left: -1rem;\n        }\n      }\n    }\n  }\n\n  .sidebar-mini.sidebar-collapse.text-sm,\n  .sidebar-mini-md.sidebar-collapse.text-sm,\n  .sidebar-mini-xs.sidebar-collapse.text-sm {\n    .main-sidebar.sidebar-focused &.nav-child-indent,\n    .main-sidebar:hover &.nav-child-indent {\n      .nav-treeview {\n        padding-left: .5rem;\n\n        .nav-treeview {\n          padding-left: 1rem;\n          margin-left: -.5rem;\n        }\n      }\n    }\n  }\n\n  .sidebar-mini.sidebar-collapse &,\n  .sidebar-mini-md.sidebar-collapse &,\n  .sidebar-mini-xs.sidebar-collapse & {\n    .sidebar {\n      > .nav-item > .nav-link {\n        .nav-icon {\n          margin-left: .55rem;\n        }\n        &.active {\n          > .nav-icon {\n            margin-left: .36rem;\n          }\n        }\n      }\n      &.nav-child-indent {\n        .nav-treeview {\n          .nav-treeview {\n            padding-left: 0;\n            margin-left: 0;\n          }\n        }\n      }\n    }\n  }\n\n  .sidebar-mini.sidebar-collapse.text-sm &,\n  .sidebar-mini-md.sidebar-collapse.text-sm &,\n  .sidebar-mini-xs.sidebar-collapse.text-sm & {\n    .sidebar {\n      > .nav-item > .nav-link {\n        .nav-icon {\n          margin-left: .75rem;\n        }\n\n        &.active {\n          > .nav-icon {\n            margin-left: calc(.75rem - 3px);\n          }\n        }\n      }\n    }\n  }\n\n  [class*=\"sidebar-dark\"] & {\n    &.nav-sidebar > .nav-item {\n      .nav-treeview,\n      > .nav-treeview {\n        background-color: rgba($white, .05);\n      }\n\n      > .nav-link.active {\n        color: $sidebar-dark-active-color;\n      }\n    }\n\n    .nav-treeview > .nav-item > .nav-link {\n      &.active,\n      &:focus,\n      &:hover {\n        background-color: transparent;\n        color: $sidebar-dark-active-color;\n      }\n    }\n  }\n\n  [class*=\"sidebar-light\"] & {\n    &.nav-sidebar > .nav-item {\n      .nav-treeview,\n      > .nav-treeview {\n        background-color: rgba($black, .05);\n      }\n\n      > .nav-link.active {\n        color: $sidebar-light-active-color;\n      }\n    }\n\n    .nav-treeview > .nav-item > .nav-link {\n      &.active,\n      &:focus,\n      &:hover {\n        background-color: transparent;\n        color: $sidebar-light-active-color;\n      }\n    }\n  }\n}\n\n.nav-collapse-hide-child {\n  .menu-open > .nav-treeview {\n    max-height: min-content;\n    animation-name: fadeIn;\n    animation-duration: $transition-speed;\n    animation-fill-mode: both;\n  }\n\n  .sidebar-collapse .sidebar:not(:hover) & {\n    .menu-open > .nav-treeview {\n      max-height: 0;\n      animation-name: fadeOut;\n      animation-duration: $transition-speed;\n      animation-fill-mode: both;\n    }\n  }\n\n  .sidebar-mini.sidebar-collapse,\n  .sidebar-mini-md.sidebar-collapse,\n  .sidebar-mini-xs.sidebar-collapse {\n    .main-sidebar.sidebar-focused &,\n    .main-sidebar:not(.sidebar-no-expand):hover & {\n      .menu-open > .nav-treeview {\n        max-height: min-content;\n        animation-name: fadeIn;\n        animation-duration: $transition-speed;\n        animation-fill-mode: both;\n      }\n    }\n  }\n}\n\n// Nav Compact\n.nav-compact {\n  .nav-link,\n  .nav-header {\n    padding-top: ($nav-link-padding-y * .5);\n    padding-bottom: ($nav-link-padding-y * .5);\n  }\n\n  .nav-header:not(:first-of-type) {\n    padding-top: ($nav-link-padding-y * 1.5);\n    padding-bottom: ($nav-link-padding-y * .5);\n  }\n\n  .nav-link > .right,\n  .nav-link > p > .right {\n    top: .465rem;\n  }\n\n  .text-sm & {\n    .nav-link > .right,\n    .nav-link > p > .right {\n      top: .7rem;\n    }\n  }\n}\n\n// Sidebar Form Control\n[class*=\"sidebar-dark\"] {\n  .form-control-sidebar,\n  .btn-sidebar {\n    background-color: lighten($sidebar-dark-bg, 5%);\n    border: 1px solid lighten($sidebar-dark-bg, 15%);\n    color: lighten(color-yiq(lighten($sidebar-dark-bg, 5%)), 15%);\n  }\n\n  .form-control-sidebar:focus,\n  .btn-sidebar:focus {\n    border: 1px solid lighten($sidebar-dark-bg, 30%);\n  }\n\n  .btn-sidebar:hover {\n    background-color: lighten($sidebar-dark-bg, 7.5%);\n  }\n\n  .btn-sidebar:focus {\n    background-color: lighten($sidebar-dark-bg, 10%);\n  }\n\n  .list-group-item {\n    background-color: lighten($sidebar-dark-bg, 7.5%);\n    border-color: lighten($sidebar-dark-bg, 15%);\n    color: $sidebar-dark-color;\n\n    &:hover {\n      background-color: lighten($sidebar-dark-bg, 10%);\n    }\n\n    &:focus {\n      background-color: lighten($sidebar-dark-bg, 12.5%);\n    }\n\n    .search-path {\n      color: $gray-500;\n    }\n  }\n}\n\n[class*=\"sidebar-light\"] {\n  .form-control-sidebar,\n  .btn-sidebar {\n    background-color: darken($sidebar-light-bg, 5%);\n    border: 1px solid darken($sidebar-light-bg, 15%);\n    color: color-yiq(darken($sidebar-light-bg, 5%));\n  }\n\n  .form-control-sidebar:focus,\n  .btn-sidebar:focus {\n    border: 1px solid darken($sidebar-light-bg, 30%);\n  }\n\n  .btn-sidebar:hover {\n    background-color: darken($sidebar-light-bg, 7.5%);\n  }\n\n  .btn-sidebar:focus {\n    background-color: darken($sidebar-light-bg, 10%);\n  }\n\n  .list-group-item {\n    border-color: darken($sidebar-light-bg, 15%);\n\n    &:hover {\n      background-color: darken($sidebar-light-bg, 7.5%);\n    }\n\n    &:focus {\n      background-color: darken($sidebar-light-bg, 10%);\n    }\n\n    .search-path {\n      color: $gray-600;\n    }\n  }\n}\n\n// Sidebar inline input-group fix\n.sidebar .form-inline .input-group {\n  width: 100%;\n  flex-wrap: nowrap;\n}\n.sidebar nav .form-inline {\n  margin-bottom: .2rem;\n}\n\n// Sidebar Collapse on Layout Boxed\n.layout-boxed:not(.sidebar-mini):not(.sidebar-mini-md):not(.sidebar-mini-xs) {\n  &.sidebar-collapse .main-sidebar {\n    margin-left: 0;\n  }\n  .content-wrapper,\n  .main-header,\n  .main-footer {\n    z-index: 9999;\n    position: relative;\n  }\n  .control-sidebar {\n    z-index: 9999;\n  }\n}\n\n// Sidebar Search\n.sidebar-collapse {\n  .form-control-sidebar,\n  .form-control-sidebar ~ .input-group-append,\n  .sidebar-search-results {\n    display: none;\n  }\n}\n\n[data-widget=\"sidebar-search\"] {\n  input[type=\"search\"] {\n    &::-ms-clear,\n    &::-ms-reveal {\n      display: none;\n      width: 0;\n      height: 0;\n    }\n\n    &::-webkit-search-cancel-button,\n    &::-webkit-search-decoration,\n    &::-webkit-search-results-button,\n    &::-webkit-search-results-decoration {\n      display: none;\n    }\n  }\n}\n\n.sidebar-search-results {\n  position: relative;\n  display: none;\n  width: 100%;\n\n  .sidebar-search-open & {\n    display: inline-block;\n  }\n\n  .search-title {\n    margin-bottom: -.1rem;\n  }\n\n  .list-group {\n    position: absolute;\n    width: 100%;\n    z-index: $zindex-main-sidebar + 1;\n\n    > .list-group-item {\n      padding: $input-padding-y $input-padding-x;\n\n      &:-moz-focusring {\n        margin-top: 0;\n        border-left: 1px solid transparent;\n        border-top: 0;\n        border-bottom: 1px solid transparent;\n      }\n\n      &:first-child {\n        margin-top: 0;\n        border-top: 0;\n        @include border-top-radius(0);\n      }\n    }\n  }\n}\n\n.sidebar-search-results .search-path {\n  font-size: $small-font-size;\n}\n\n.sidebar-search-open {\n  .btn,\n  .form-control {\n    @include border-bottom-radius(0);\n  }\n}\n\n// Custom Area\n.sidebar-custom {\n  [class*=\"sidebar-dark\"] & {\n    border-top: 1px solid lighten($dark, 12%);\n  }\n\n  [class*=\"sidebar-light\"] & {\n    border-top: 1px solid $gray-300;\n  }\n}\n\n.layout-fixed {\n  &.sidebar-collapse {\n    .hide-on-collapse {\n      display: none;\n    }\n  }\n\n  &.sidebar-collapse:hover {\n    .hide-on-collapse {\n      display: block;\n    }\n  }\n\n  &.text-sm .main-sidebar-custom {\n    .sidebar {\n      height: calc(100% - ((#{$main-header-height-sm-inner} + #{$sidebar-custom-height * .95}) + #{$main-header-bottom-border-width}));\n    }\n    .sidebar-custom {\n      height: $sidebar-custom-height * .95;\n      padding: $sidebar-custom-padding-x $sidebar-custom-padding-y;\n    }\n  }\n  .main-sidebar-custom {\n    .sidebar {\n      height: calc(100% - ((#{$main-header-height-inner} + #{$sidebar-custom-height}) + #{$main-header-bottom-border-width}));\n    }\n\n    .sidebar-custom {\n      height: $sidebar-custom-height;\n      padding: $sidebar-custom-padding-x $sidebar-custom-padding-y;\n    }\n\n    height: stretch;\n  }\n\n  .main-sidebar-custom-lg {\n    .sidebar {\n      height: calc(100% - ((#{$main-header-height-inner} + #{$sidebar-custom-height-lg}) + #{$main-header-bottom-border-width}));\n    }\n\n    .sidebar-custom {\n      height: $sidebar-custom-height-lg;\n    }\n  }\n\n  .main-sidebar-custom-xl {\n    .sidebar {\n      height: calc(100% - ((#{$main-header-height-inner} + #{$sidebar-custom-height-xl}) + #{$main-header-bottom-border-width}));\n    }\n\n    .sidebar-custom {\n      height: $sidebar-custom-height-xl;\n    }\n  }\n\n  .main-sidebar-custom,\n  .main-sidebar-custom-lg,\n  .main-sidebar-custom-xl {\n    .pos-right {\n      position: absolute;\n      right: .5rem;\n    }\n  }\n}\n\n.sidebar-hidden,\n.sidebar-hidden.sidebar-mini.sidebar-collapse {\n  .main-sidebar {\n    display: none !important;\n  }\n  .content-wrapper,\n  .main-header {\n    margin-left: 0 !important;\n  }\n}\n\n@include dark-mode() {\n  @each $name, $color in $theme-colors-alt {\n    .sidebar-dark-#{$name},\n    .sidebar-light-#{$name} {\n      @include sidebar-color($color);\n    }\n  }\n\n  @each $name, $color in $colors-alt {\n    .sidebar-dark-#{$name},\n    .sidebar-light-#{$name} {\n      @include sidebar-color($color);\n    }\n  }\n\n  [class*=\"sidebar-light-\"] {\n    .sidebar {\n      a {\n        color: $sidebar-light-color;\n\n        &:hover {\n          text-decoration: none;\n        }\n      }\n    }\n  }\n}\n\n//\n","//\n// Mixins: Miscellaneous\n//\n\n// ETC\n@mixin translate($x, $y) {\n  transform: translate($x, $y);\n}\n\n// Different radius each side\n@mixin border-radius-sides($top-left, $top-right, $bottom-left, $bottom-right) {\n  border-radius: $top-left $top-right $bottom-left $bottom-right;\n}\n\n@mixin calc($property, $expression) {\n  #{$property}: calc(#{$expression});\n}\n\n@mixin rotate($value) {\n  transform: rotate($value);\n}\n\n@mixin animation($animation) {\n  animation: $animation;\n}\n\n// Gradient background\n@mixin gradient($color: #f5f5f5, $start: #eee, $stop: $white) {\n  background-color: $color;\n  background-image: gradient(linear, left bottom, left top, color-stop(0, $start), color-stop(1, $stop));\n}\n\n//\n","//\n// Mixins: Sidebar\n//\n\n// Sidebar Color\n@mixin sidebar-color($color) {\n  .nav-sidebar > .nav-item {\n    > .nav-link.active {\n      background-color: $color;\n      color: color-yiq($color);\n    }\n  }\n\n  .nav-sidebar.nav-legacy > .nav-item {\n    > .nav-link.active {\n      border-color: $color;\n    }\n  }\n}\n\n// Sidebar Mini Breakpoints\n@mixin sidebar-mini-breakpoint() {\n  // A fix for text overflow while transitioning from sidebar mini to full sidebar\n  .nav-sidebar,\n  .nav-sidebar > .nav-header,\n  .nav-sidebar .nav-link {\n    white-space: nowrap;\n  }\n\n  // When the sidebar is collapsed...\n  &.sidebar-collapse {\n    .d-hidden-mini {\n      display: none;\n    }\n\n    // Apply the new margins to the main content and footer\n    .content-wrapper,\n    .main-footer,\n    .main-header {\n      margin-left: $sidebar-mini-width !important;\n    }\n\n    // Make the sidebar headers\n    .nav-sidebar .nav-header {\n      display: none;\n    }\n\n    .sidebar .nav-sidebar .nav-link p {\n      width: 0;\n      white-space: nowrap;\n    }\n\n    .sidebar .user-panel > .info,\n    .sidebar .nav-sidebar .nav-link p,\n    .brand-text {\n      margin-left: -10px;\n      animation-name: fadeOut;\n      animation-duration: $transition-speed;\n      animation-fill-mode: both;\n      visibility: hidden;\n    }\n\n    .logo-xl {\n      animation-name: fadeOut;\n      animation-duration: $transition-speed;\n      animation-fill-mode: both;\n      visibility: hidden;\n    }\n\n    .logo-xs {\n      display: inline-block;\n      animation-name: fadeIn;\n      animation-duration: $transition-speed;\n      animation-fill-mode: both;\n      visibility: visible;\n    }\n\n    // Modify the sidebar to shrink instead of disappearing\n    .main-sidebar {\n      overflow-x: hidden;\n\n      &,\n      &::before {\n        // Don't go away! Just shrink\n        margin-left: 0;\n        width: $sidebar-mini-width;\n      }\n\n      .user-panel {\n        .image {\n          float: none;\n        }\n      }\n\n      &:not(.sidebar-no-expand) {\n        &:hover,\n        &.sidebar-focused {\n          width: $sidebar-width;\n\n          .brand-link {\n            width: $sidebar-width;\n          }\n\n          .user-panel {\n            text-align: left;\n\n            .image {\n              float: left;\n            }\n          }\n\n          .user-panel > .info,\n          .sidebar .nav-sidebar .nav-link p,\n          .brand-text,\n          .logo-xl {\n            display: inline-block;\n            margin-left: 0;\n            animation-name: fadeIn;\n            animation-duration: $transition-speed;\n            animation-fill-mode: both;\n            visibility: visible;\n          }\n\n          .logo-xs {\n            animation-name: fadeOut;\n            animation-duration: $transition-speed;\n            animation-fill-mode: both;\n            visibility: hidden;\n          }\n\n          .brand-image {\n            margin-right: .5rem;\n          }\n\n          // Make the sidebar links, menus, labels, badges\n          // and angle icons disappear\n          .sidebar-form,\n          .user-panel > .info {\n            display: block !important;\n            transform: translateZ(0);\n          }\n\n          .nav-sidebar > .nav-item > .nav-link > span {\n            display: inline-block !important;\n          }\n        }\n      }\n    }\n\n    // Make an element visible only when sidebar mini is active\n    .visible-sidebar-mini {\n      display: block !important;\n    }\n\n    &.layout-fixed {\n      .main-sidebar:hover {\n        .brand-link {\n          width: $sidebar-width;\n        }\n      }\n\n      .brand-link {\n        width: $sidebar-mini-width;\n      }\n    }\n  }\n}\n","//\n// Component: Sidebar Mini\n//\n\n// Logo style\n.logo-xs,\n.logo-xl {\n  opacity: 1;\n  position: absolute;\n  visibility: visible;\n\n  &.brand-image-xs {\n    left: 18px;\n    top: 12px;\n  }\n\n  &.brand-image-xl {\n    left: 12px;\n    top: 6px;\n  }\n}\n\n.logo-xs {\n  opacity: 0;\n  visibility: hidden;\n\n  &.brand-image-xl {\n    left: 16px;\n    top: 8px;\n  }\n}\n\n.brand-link {\n  &.logo-switch {\n    &::before {\n      content: \"\\00a0\";\n    }\n  }\n}\n\n// Add sidebar-mini class to the body tag to activate this feature\n.sidebar-mini {\n  @include media-breakpoint-up(lg) {\n    @include sidebar-mini-breakpoint ();\n  }\n}\n@include media-breakpoint-down(md) {\n  .sidebar-mini.sidebar-collapse .main-sidebar {\n    box-shadow: none !important;\n  }\n}\n\n.sidebar-mini-md {\n  @include media-breakpoint-up(md) {\n    @include sidebar-mini-breakpoint ();\n  }\n}\n@include media-breakpoint-down(sm) {\n  .sidebar-mini-md.sidebar-collapse .main-sidebar {\n    box-shadow: none !important;\n  }\n}\n\n.sidebar-mini-xs {\n  @include media-breakpoint-up(xs) {\n    @include sidebar-mini-breakpoint ();\n  }\n}\n\n.sidebar-mini,\n.sidebar-mini-md,\n.sidebar-mini-xs {\n  .main-sidebar {\n    .nav-child-indent .nav-treeview {\n      .nav-link {\n        width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 1rem);\n      }\n\n      .nav-treeview {\n        .nav-link {\n          width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 2rem);\n        }\n\n        .nav-treeview {\n          .nav-link {\n            width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 3rem);\n          }\n\n          .nav-treeview {\n            .nav-link {\n              width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 4rem);\n            }\n\n            .nav-treeview {\n              .nav-link {\n                width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 5rem);\n              }\n            }\n          }\n        }\n      }\n    }\n    .nav-legacy {\n      .nav-link {\n        width: $sidebar-width;\n      }\n      &.nav-child-indent {\n        .nav-treeview {\n          .nav-link {\n            width: calc(#{$sidebar-width} - 1rem);\n          }\n\n          .nav-treeview {\n            .nav-link {\n              width: calc(#{$sidebar-width} - 1rem - 1rem);\n            }\n\n            .nav-treeview {\n              .nav-link {\n                width: calc(#{$sidebar-width} - 1rem - 2rem);\n              }\n\n              .nav-treeview {\n                .nav-link {\n                  width: calc(#{$sidebar-width} - 1rem - 3rem);\n                }\n\n                .nav-treeview {\n                  .nav-link {\n                    width: calc(#{$sidebar-width} - 1rem - 4rem);\n                  }\n                }\n              }\n            }\n          }\n        }\n      }\n    }\n    .nav-flat {\n      .nav-link {\n        width: $sidebar-width;\n      }\n      &.nav-child-indent {\n        .nav-treeview {\n          .nav-link {\n            width: calc(#{$sidebar-width});\n          }\n\n          .nav-treeview {\n            .nav-link {\n              width: calc(#{$sidebar-width} - .2rem);\n            }\n\n            .nav-treeview {\n              .nav-link {\n                width: calc(#{$sidebar-width} - .2rem * 2);\n              }\n\n              .nav-treeview {\n                .nav-link {\n                  width: calc(#{$sidebar-width} - .2rem * 3);\n                }\n\n                .nav-treeview {\n                  .nav-link {\n                    width: calc(#{$sidebar-width} - .2rem * 4);\n                  }\n                }\n              }\n            }\n          }\n        }\n      }\n    }\n    .nav-child-indent.nav-compact .nav-treeview {\n      .nav-link {\n        width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - .5rem);\n      }\n\n      .nav-treeview {\n        .nav-link {\n          width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 1rem);\n        }\n\n        .nav-treeview {\n          .nav-link {\n            width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 1.5rem);\n          }\n\n          .nav-treeview {\n            .nav-link {\n              width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 2rem);\n            }\n\n            .nav-treeview {\n              .nav-link {\n                width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 2.5rem);\n              }\n            }\n          }\n        }\n      }\n    }\n    .nav-child-indent.nav-legacy.nav-compact {\n      .nav-link {\n        width: $sidebar-width;\n      }\n      .nav-treeview {\n        .nav-link {\n          width: calc(#{$sidebar-width} - .5rem);\n        }\n\n        .nav-treeview {\n          .nav-link {\n            width: calc(#{$sidebar-width} - .5rem * 2);\n          }\n\n          .nav-treeview {\n            .nav-link {\n              width: calc(#{$sidebar-width} - .5rem * 3);\n            }\n\n            .nav-treeview {\n              .nav-link {\n                width: calc(#{$sidebar-width} - .5rem * 4);\n              }\n\n              .nav-treeview {\n                .nav-link {\n                  width: calc(#{$sidebar-width} - .5rem * 5);\n                }\n              }\n            }\n          }\n        }\n      }\n    }\n    .nav-link {\n      width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2);\n      @include transition(width $transition-fn $transition-speed);\n    }\n  }\n}\n\n.sidebar-collapse {\n  &.sidebar-mini,\n  &.sidebar-mini-md,\n  &.sidebar-mini-xs {\n    .main-sidebar {\n\n      // Hide the sidebar search results when mini mode is active.\n      .sidebar-search-results {\n        display: none;\n      }\n\n      .nav-sidebar {\n        .nav-link {\n          width: $sidebar-mini-width - $sidebar-padding-x * 2;\n        }\n\n        &.nav-flat,\n        &.nav-legacy {\n          .nav-link {\n            width: $sidebar-mini-width;\n          }\n        }\n        &.nav-child-indent.nav-compact {\n          .nav-treeview {\n            padding-left: 0 !important;\n            margin-left: 0 !important;\n          }\n\n          .nav-link {\n            width: calc(#{$sidebar-mini-width} - #{$sidebar-padding-x} * 2);\n          }\n        }\n      }\n\n      &.sidebar-focused,\n      &:hover {\n        &:not(.hide-nav-header-on-hover) {\n          .nav-header {\n            display: inline-block;\n          }\n        }\n\n        // Show sidebar search when hover/focus on the sidebar mini mode.\n        &:not(.sidebar-no-expand) {\n          .nav-link {\n            width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2);\n          }\n          .form-control-sidebar {\n            display: inline-block;\n          }\n          .form-control-sidebar ~ .input-group-append {\n            display: flex;\n          }\n          .sidebar-search-open .sidebar-search-results {\n            display: inline-block;\n          }\n        }\n\n        .nav-child-indent {\n          .nav-link {\n            width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2);\n          }\n        }\n        .nav-legacy {\n          .nav-link {\n            width: $sidebar-width;\n          }\n          &.nav-child-indent {\n            .nav-treeview {\n              .nav-link {\n                width: calc(#{$sidebar-width} - 1rem);\n              }\n\n              .nav-treeview {\n                .nav-link {\n                  width: calc(#{$sidebar-width} - 1rem - 1rem);\n                }\n\n                .nav-treeview {\n                  .nav-link {\n                    width: calc(#{$sidebar-width} - 1rem - 2rem);\n                  }\n\n                  .nav-treeview {\n                    .nav-link {\n                      width: calc(#{$sidebar-width} - 1rem - 3rem);\n                    }\n\n                    .nav-treeview {\n                      .nav-link {\n                        width: calc(#{$sidebar-width} - 1rem - 4rem);\n                      }\n                    }\n                  }\n                }\n              }\n            }\n          }\n        }\n        .nav-flat {\n          .nav-link {\n            width: $sidebar-width;\n          }\n          &.nav-child-indent {\n            .nav-treeview {\n              .nav-link {\n                width: calc(#{$sidebar-width});\n              }\n\n              .nav-treeview {\n                .nav-link {\n                  width: calc(#{$sidebar-width} - .2rem);\n                }\n\n                .nav-treeview {\n                  .nav-link {\n                    width: calc(#{$sidebar-width} - .2rem * 2);\n                  }\n\n                  .nav-treeview {\n                    .nav-link {\n                      width: calc(#{$sidebar-width} - .2rem * 3);\n                    }\n\n                    .nav-treeview {\n                      .nav-link {\n                        width: calc(#{$sidebar-width} - .2rem * 4);\n                      }\n                    }\n                  }\n                }\n              }\n            }\n          }\n        }\n        .nav-child-indent.nav-compact {\n          .nav-link {\n            width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2);\n          }\n        }\n        .nav-child-indent.nav-legacy.nav-compact {\n          .nav-link {\n            width: $sidebar-width;\n          }\n          .nav-treeview {\n            .nav-link {\n              width: calc(#{$sidebar-width} - .5rem);\n            }\n\n            .nav-treeview {\n              .nav-link {\n                width: calc(#{$sidebar-width} - .5rem * 2);\n              }\n\n              .nav-treeview {\n                .nav-link {\n                  width: calc(#{$sidebar-width} - .5rem * 3);\n                }\n\n                .nav-treeview {\n                  .nav-link {\n                    width: calc(#{$sidebar-width} - .5rem * 4);\n                  }\n\n                  .nav-treeview {\n                    .nav-link {\n                      width: calc(#{$sidebar-width} - .5rem * 5);\n                    }\n                  }\n                }\n              }\n            }\n          }\n        }\n      }\n    }\n\n    .sidebar-no-expand.main-sidebar.sidebar-focused,\n    .sidebar-no-expand.main-sidebar:hover {\n      width: $sidebar-mini-width;\n\n      .nav-header {\n        display: none;\n      }\n\n      .brand-link {\n        width: $sidebar-mini-width !important;\n      }\n\n      .user-panel .image {\n        float: none !important;\n      }\n\n      .logo-xs {\n        animation-name: fadeIn;\n        animation-duration: $transition-speed;\n        animation-fill-mode: both;\n        visibility: visible;\n      }\n\n      .logo-xl {\n        animation-name: fadeOut;\n        animation-duration: $transition-speed;\n        animation-fill-mode: both;\n        visibility: hidden;\n      }\n\n      .nav-sidebar.nav-child-indent .nav-treeview {\n        padding-left: 0;\n      }\n\n      .sidebar {\n        .brand-text,\n        .user-panel > .info,\n        .nav-sidebar .nav-link p {\n          margin-left: -10px;\n          animation-name: fadeOut;\n          animation-duration: $transition-speed;\n          animation-fill-mode: both;\n          visibility: hidden;\n          display: inline-block;\n          width: 0;\n        }\n\n        .nav-sidebar > .nav-item .nav-icon {\n          margin-right: 0;\n        }\n      }\n    }\n  }\n}\n\n.nav-sidebar {\n  position: relative;\n\n  &:hover {\n    overflow: visible;\n  }\n}\n\n.sidebar-form,\n.nav-sidebar > .nav-header {\n  overflow: hidden;\n  text-overflow: clip;\n}\n\n.nav-sidebar .nav-item > .nav-link {\n  position: relative;\n\n  > .float-right {\n    margin-top: -7px;\n    position: absolute;\n    right: 10px;\n    top: 50%;\n  }\n}\n\n.sidebar .nav-link p,\n.main-sidebar .brand-text,\n.main-sidebar .logo-xs,\n.main-sidebar .logo-xl,\n.sidebar .user-panel .info {\n  @include transition(margin-left $transition-speed linear, opacity $transition-speed ease, visibility $transition-speed ease);\n}\n","//\n// Component: Control Sidebar\n//\n\nhtml.control-sidebar-animate {\n  overflow-x: hidden;\n}\n\n.control-sidebar {\n  bottom: $main-footer-height;\n  position: absolute;\n  top: $main-header-height;\n  z-index: $zindex-control-sidebar;\n\n  &,\n  &::before {\n    bottom: $main-footer-height;\n    display: none;\n    right: -$control-sidebar-width;\n    width: $control-sidebar-width;\n    @include transition(\n      right $transition-speed $transition-fn,\n      display $transition-speed $transition-fn\n    );\n  }\n\n  &::before {\n    content: \"\";\n    display: block;\n    position: fixed;\n    top: 0;\n    z-index: -1;\n  }\n}\n\nbody.text-sm {\n  .control-sidebar {\n    bottom: $main-footer-height-sm;\n    top: $main-header-height-sm;\n  }\n}\n\n.main-header.text-sm ~ .control-sidebar {\n  top: $main-header-height-sm;\n}\n\n.main-footer.text-sm ~ .control-sidebar {\n  bottom: $main-footer-height-sm;\n}\n\n.control-sidebar-push-slide {\n  .content-wrapper,\n  .main-footer {\n    @include transition(margin-right $transition-speed $transition-fn);\n  }\n}\n\n// Control sidebar open state\n.control-sidebar-open {\n  .control-sidebar {\n    display: block !important;\n\n    &,\n    &::before {\n      right: 0;\n    }\n  }\n\n  &.control-sidebar-push,\n  &.control-sidebar-push-slide {\n    .content-wrapper,\n    .main-footer {\n      margin-right: $control-sidebar-width;\n    }\n  }\n}\n\n// Control sidebar slide over content state\n.control-sidebar-slide-open {\n  .control-sidebar {\n    display: block;\n\n    &,\n    &::before {\n      right: 0;\n      @include transition(\n        right $transition-speed $transition-fn,\n        display $transition-speed $transition-fn\n      );\n    }\n  }\n\n  &.control-sidebar-push,\n  &.control-sidebar-push-slide {\n    .content-wrapper,\n    .main-footer {\n      margin-right: $control-sidebar-width;\n    }\n  }\n}\n\n// Dark skin\n.control-sidebar-dark {\n  background-color: $sidebar-dark-bg;\n\n  &,\n  a,\n  .nav-link {\n    color: $sidebar-dark-color;\n  }\n\n  a:hover {\n    color: $sidebar-dark-hover-color;\n  }\n\n  // Headers and labels\n  h1,\n  h2,\n  h3,\n  h4,\n  h5,\n  h6,\n  label {\n    color: $sidebar-dark-hover-color;\n  }\n\n  // Tabs\n  .nav-tabs {\n    background-color: $sidebar-dark-hover-bg;\n    border-bottom: 0;\n    margin-bottom: 5px;\n\n    .nav-item {\n      margin: 0;\n    }\n\n    .nav-link {\n      border-radius: 0;\n      padding: 10px 20px;\n      position: relative;\n      text-align: center;\n\n      &,\n      &:hover,\n      &:active,\n      &:focus,\n      &.active {\n        border: 0;\n      }\n\n      &:hover,\n      &:active,\n      &:focus,\n      &.active {\n        border-bottom-color: transparent;\n        border-left-color: transparent;\n        border-top-color: transparent;\n        color: $sidebar-dark-hover-color;\n      }\n\n      &.active {\n        background-color: $sidebar-dark-bg;\n      }\n    }\n  }\n\n  .tab-pane {\n    padding: 10px 15px;\n  }\n}\n\n// Light skin\n.control-sidebar-light {\n  color: lighten($sidebar-light-color, 10%);\n\n  //  Background\n  background-color: $sidebar-light-bg;\n  border-left: $main-header-bottom-border;\n}\n","//\n// Component: Dropdown\n//\n\n// General Dropdown Rules\n//.dropdown-item {\n//  &:first-of-type {\n//    @include border-top-radius($border-radius);\n//  }\n//  &:last-of-type {\n//    @include border-bottom-radius($border-radius);\n//  }\n//}\n\n.text-sm {\n  .dropdown-menu {\n    font-size: $font-size-sm !important;\n  }\n\n  .dropdown-toggle::after {\n    vertical-align: .2rem;\n  }\n}\n\n.dropdown-item-title {\n  font-size: $font-size-base;\n  margin: 0;\n}\n\n.dropdown-icon {\n  &::after {\n    margin-left: 0;\n  }\n}\n\n// Dropdown Sizes\n.dropdown-menu-lg {\n  max-width: 300px;\n  min-width: 280px;\n  padding: 0;\n\n  .dropdown-divider {\n    margin: 0;\n  }\n\n  .dropdown-item {\n    padding: $dropdown-padding-y $dropdown-item-padding-x;\n  }\n\n  p {\n    margin: 0;\n    white-space: normal;\n  }\n}\n\n// Dropdown Submenu\n.dropdown-submenu {\n  position: relative;\n\n  > a::after {\n    @include caret-right ();\n    float: right;\n    margin-left: .5rem;\n    margin-top: .5rem;\n  }\n\n  > .dropdown-menu {\n    left: 100%;\n    margin-left: 0;\n    margin-top: 0;\n    top: 0;\n  }\n}\n\n// Dropdown Hover\n.dropdown-hover {\n  &:hover,\n  &.nav-item.dropdown:hover,\n  .dropdown-submenu:hover,\n  &.dropdown-submenu:hover {\n    > .dropdown-menu {\n      display: block;\n    }\n  }\n}\n\n\n// Dropdown Sizes\n.dropdown-menu-xl {\n  max-width: 420px;\n  min-width: 360px;\n  padding: 0;\n\n  .dropdown-divider {\n    margin: 0;\n  }\n\n  .dropdown-item {\n    padding: $dropdown-padding-y $dropdown-item-padding-x;\n  }\n\n  p {\n    margin: 0;\n    white-space: normal;\n  }\n}\n\n// Dropdown header and footer\n.dropdown-footer,\n.dropdown-header {\n  display: block;\n  font-size: $font-size-sm;\n  padding: .5rem $dropdown-item-padding-x;\n  text-align: center;\n}\n\n// Add fade animation to dropdown menus by appending\n// the class .animated-dropdown-menu to the .dropdown-menu ul (or ol)\n.open:not(.dropup) > .animated-dropdown-menu {\n  @include animation(flipInX .7s both);\n  backface-visibility: visible !important;\n}\n\n// Fix dropdown menu in navbars\n.navbar-custom-menu > .navbar-nav {\n  > li {\n    position: relative;\n    > .dropdown-menu {\n      position: absolute;\n      right: 0;\n      left: auto;\n    }\n  }\n}\n\n@include media-breakpoint-down(sm) {\n  .navbar-custom-menu > .navbar-nav {\n    float: right;\n    > li {\n      position: static;\n      > .dropdown-menu {\n        position: absolute;\n        right: 5%;\n        left: auto;\n        border: 1px solid #ddd;\n        background-color: $white;\n      }\n    }\n  }\n}\n\n// User Menu\n.navbar-nav > .user-menu {\n  > .nav-link::after {\n    content: none;\n  }\n\n  > .dropdown-menu {\n    @include border-top-radius(0);\n    padding: 0;\n    width: 280px;\n\n    &,\n    > .user-body {\n      @include border-bottom-radius(4px);\n    }\n\n    // Header menu\n    > li.user-header {\n      height: 175px;\n      padding: 10px;\n      text-align: center;\n\n      // User image\n      > img {\n        z-index: 5;\n        height: 90px;\n        width: 90px;\n        border: 3px solid;\n        border-color: transparent;\n        border-color: rgba(255, 255, 255, .2);\n      }\n\n      > p {\n        z-index: 5;\n        font-size: 17px;\n        //text-shadow: 2px 2px 3px #333333;\n        margin-top: 10px;\n\n        > small {\n          display: block;\n          font-size: 12px;\n        }\n      }\n    }\n\n    // Menu Body\n    > .user-body {\n      @include clearfix ();\n      border-bottom: 1px solid $gray-700;\n      border-top: 1px solid $gray-300;\n      padding: 15px;\n\n      a {\n        @include media-breakpoint-up(sm) {\n          background-color: $white !important;\n          color: $gray-700 !important;\n        }\n      }\n    }\n\n    // Menu Footer\n    > .user-footer {\n      @include clearfix ();\n      background-color: $gray-100;\n      padding: 10px;\n\n      .btn-default {\n        color: $gray-600;\n\n        &:hover {\n          @include media-breakpoint-up(sm) {\n            background-color: $gray-100;\n          }\n        }\n      }\n    }\n  }\n\n  .user-image {\n    @include media-breakpoint-up(sm) {\n      float: none;\n      line-height: 10px;\n      margin-right: .4rem;\n      margin-top: -8px;\n    }\n\n    border-radius: 50%;\n    float: left;\n    height: $sidebar-user-image-width;\n    margin-right: 10px;\n    margin-top: -2px;\n    width: $sidebar-user-image-width;\n  }\n}\n\n@include dark-mode () {\n  .dropdown-menu {\n    background-color: $dark;\n    color: $white;\n  }\n  .dropdown-item {\n    color: $white;\n\n    &:focus,\n    &:hover {\n      background-color: lighten($dark, 5%);\n    }\n  }\n  .dropdown-divider {\n    border-color: $gray-600;\n  }\n\n  .navbar-nav > .user-menu > .dropdown-menu {\n    > .user-footer {\n      background-color: lighten($dark, 2.5%);\n      color: $white;\n\n      .btn-default {\n        color: $white;\n\n        &:hover,\n        &:focus {\n          background-color: lighten($dark, 5%);\n          color: $gray-300;\n        }\n        &:focus {\n          background-color: lighten($dark, 7.5%);\n        }\n      }\n    }\n    > .user-body {\n      border-color: $gray-600;\n    }\n    > .user-body a {\n      background-color: transparent !important;\n      color: $white !important;\n\n      &:hover,\n      &:focus {\n        color: $gray-400 !important;\n      }\n    }\n  }\n}\n","//\n// Component: Nav\n//\n\n.nav-pills {\n  .nav-link {\n    color: $gray-600;\n\n    &:not(.active):hover {\n      color: theme-color(\"primary\");\n    }\n  }\n\n  .nav-item {\n    &.dropdown.show {\n      .nav-link:hover {\n        color: $dropdown-link-active-color;\n      }\n    }\n  }\n}\n\n// Vertical Tabs\n.nav-tabs.flex-column {\n  border-bottom: 0;\n  border-right: $nav-tabs-border-width solid $nav-tabs-border-color;\n\n  .nav-link {\n    border-bottom-left-radius: $nav-tabs-border-radius;\n    border-top-right-radius: 0;\n    margin-right: -$nav-tabs-border-width;\n\n    @include hover-focus () {\n      border-color: $gray-200 transparent $gray-200 $gray-200;\n    }\n  }\n\n  .nav-link.active,\n  .nav-item.show .nav-link {\n    border-color: $gray-300 transparent $gray-300 $gray-300;\n  }\n\n  &.nav-tabs-right {\n    border-left: $nav-tabs-border-width solid $nav-tabs-border-color;\n    border-right: 0;\n\n    .nav-link {\n      border-bottom-left-radius: 0;\n      border-bottom-right-radius: $nav-tabs-border-radius;\n      border-top-left-radius: 0;\n      border-top-right-radius: $nav-tabs-border-radius;\n      margin-left: -$nav-tabs-border-width;\n\n      @include hover-focus () {\n        border-color: $gray-200 $gray-200 $gray-200 transparent;\n      }\n    }\n\n    .nav-link.active,\n    .nav-item.show .nav-link {\n      border-color: $gray-300 $gray-300 $gray-300 transparent;\n    }\n  }\n}\n\n.navbar-no-expand {\n  flex-direction: row;\n\n  .nav-link {\n    padding-left: $navbar-nav-link-padding-x;\n    padding-right: $navbar-nav-link-padding-x;\n  }\n\n  .dropdown-menu {\n    position: absolute;\n  }\n}\n\n// Color variants\n@each $color, $value in $theme-colors {\n  @if $color == dark or $color == light {\n    .navbar-#{$color} {\n      background-color: $value;\n      @if $color == dark {\n        border-color: lighten($dark, 10%);\n      }\n    }\n  }\n}\n\n@each $color, $value in $theme-colors {\n  @if $color != dark and $color != light {\n    @include navbar-variant($color, $value);\n  }\n}\n\n@each $color, $value in $colors {\n  @include navbar-variant($color, $value);\n}\n\n.navbar-nav-not-expanded {\n  flex-direction: row;\n\n  .dropdown-menu {\n    position: absolute;\n  }\n\n  .nav-link {\n    padding-right: $navbar-nav-link-padding-x;\n    padding-left: $navbar-nav-link-padding-x;\n  }\n}\n\n\n@include dark-mode () {\n  .nav-pills .nav-link {\n    color: $gray-400;\n  }\n\n  .nav-tabs {\n    border-color: lighten($dark, 15%);\n\n    .nav-link:focus,\n    .nav-link:hover {\n      border-color: lighten($dark, 15%);\n    }\n\n    .nav-item.show .nav-link,\n    .nav-link.active {\n      background-color: $dark;\n      border-color: lighten($dark, 15%) lighten($dark, 15%) transparent lighten($dark, 15%);\n      color: $white;\n    }\n\n    &.flex-column {\n      .nav-item.show .nav-link,\n      .nav-link {\n        &.active,\n        &:focus,\n        &:hover {\n          border-color: lighten($dark, 15%) transparent lighten($dark, 15%) lighten($dark, 15%);\n        }\n        &:focus,\n        &:hover {\n          background-color: lighten($dark, 5%);\n        }\n      }\n      &.nav-tabs-right {\n        border-color: lighten($dark, 15%);\n        .nav-link {\n          &.active,\n          &:focus,\n          &:hover {\n            border-color: lighten($dark, 15%) lighten($dark, 15%) lighten($dark, 15%) transparent;\n          }\n        }\n      }\n    }\n  }\n\n  // Color variants\n  @each $color, $value in $theme-colors-alt {\n    @if $color == dark or $color == light {\n      .navbar-#{$color} {\n        background-color: $value;\n        @if $color == dark {\n          border-color: lighten($dark, 10%);\n        }\n      }\n    }\n  }\n\n  @each $color, $value in $theme-colors-alt {\n    @if $color != dark and $color != light {\n      @include navbar-variant($color, $value);\n    }\n  }\n\n  @each $color, $value in $colors-alt {\n    @include navbar-variant($color, $value);\n  }\n}\n","//\n// Mixins: Navbar\n//\n\n// Navbar Variant\n@mixin navbar-variant($name, $color) {\n  .navbar-#{$name} {\n    background-color: $color;\n    color: color-yiq($color);\n\n    &.navbar-light {\n      .form-control-navbar {\n        &::placeholder {\n          color: rgba($gray-800, .8);\n        }\n        &,\n        + .input-group-append > .btn-navbar {\n          background-color: darken($color, 4%);\n          border-color: darken($color, 9%);\n          color: rgba($gray-800, .8);\n        }\n\n        &:focus {\n          &::placeholder {\n            color: $gray-800;\n          }\n          &,\n          + .input-group-append .btn-navbar {\n            background-color: darken($color, 5%);\n            border-color: darken($color, 9%) !important;\n            color: $gray-800;\n          }\n        }\n      }\n    }\n    &.navbar-dark {\n      .form-control-navbar {\n        &::placeholder {\n          color: rgba($white, .8);\n        }\n        &,\n        + .input-group-append > .btn-navbar {\n          background-color: lighten($color, 4%);\n          border-color: lighten($color, 9%);\n          color: rgba($white, .8);\n        }\n\n        &:focus {\n          &::placeholder {\n            color: $white;\n          }\n          &,\n          + .input-group-append .btn-navbar {\n            background-color: lighten($color, 5%);\n            border-color: lighten($color, 9%) !important;\n            color: $white;\n          }\n        }\n      }\n    }\n  }\n}\n","//\n// Component: Pagination\n//\n\n.pagination-month {\n  .page-item {\n    justify-self: stretch;\n\n    .page-link {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      flex-direction: column;\n      box-shadow: none;\n    }\n    &:first-child,\n    &:last-child {\n      .page-link {\n        height: 100%;\n        font-size: $font-size-lg;\n      }\n    }\n    .page-month {\n      margin-bottom: 0;\n      font-size: $font-size-lg;\n      font-weight: $font-weight-bold;\n    }\n    .page-year {\n      margin-bottom: 0;\n    }\n  }\n\n  &.pagination-lg {\n    .page-month {\n      font-size: ($font-size-lg * 1.25);\n    }\n  }\n  &.pagination-sm {\n    .page-month {\n      font-size: ($font-size-base);\n    }\n  }\n}\n\n@include dark-mode () {\n  .page-item {\n    &.disabled a,\n    &.disabled .page-link {\n      background-color: lighten($dark, 2.5%) !important;\n      border-color: $gray-600 !important;\n      color: $gray-600;\n    }\n\n    .page-link {\n      color: $primary-alt;\n    }\n\n    &.active {\n      .page-link {\n        background-color: $primary-alt;\n        border-color: $primary-alt;\n        color: $white;\n\n        &:hover,\n        &:focus {\n          color: $gray-400 !important;\n        }\n      }\n    }\n    &:not(.active) {\n      .page-link {\n        background-color: $dark;\n        border-color: $gray-600;\n\n        &:hover,\n        &:focus {\n          color: lighten($primary-alt, 5%);\n          background-color: lighten($dark, 5%);\n        }\n      }\n    }\n  }\n}\n","//\n// Misc: Miscellaneous\n//\n\n.border-transparent {\n  border-color: transparent !important;\n}\n\n// Description Blocks\n.description-block {\n  display: block;\n  margin: 10px 0;\n  text-align: center;\n\n  &.margin-bottom {\n    margin-bottom: 25px;\n  }\n\n  > .description-header {\n    font-size: 16px;\n    font-weight: 600;\n    margin: 0;\n    padding: 0;\n  }\n\n  > .description-text {\n    text-transform: uppercase;\n  }\n\n  // Description Block Extension\n  .description-icon {\n    font-size: 16px;\n  }\n}\n\n// List utility classes\n.list-group-unbordered {\n  > .list-group-item {\n    border-left: 0;\n    border-radius: 0;\n    border-right: 0;\n    padding-left: 0;\n    padding-right: 0;\n  }\n}\n\n.list-header {\n  color: $gray-600;\n  font-size: 15px;\n  font-weight: 700;\n  padding: 10px 4px;\n}\n\n.list-seperator {\n  background-color: $card-border-color;\n  height: 1px;\n  margin: 15px 0 9px;\n}\n\n.list-link {\n  > a {\n    color: $gray-600;\n    padding: 4px;\n\n    &:hover {\n      color: $gray-900;\n    }\n  }\n}\n\n// User block\n.user-block {\n  float: left;\n\n  img {\n    float: left;\n    height: 40px;\n    width: 40px;\n  }\n\n  .username,\n  .description,\n  .comment {\n    display: block;\n    margin-left: 50px;\n  }\n\n  .username {\n    font-size: 16px;\n    font-weight: 600;\n    margin-top: -1px;\n  }\n\n  .description {\n    color: $gray-600;\n    font-size: 13px;\n    margin-top: -3px;\n  }\n\n  &.user-block-sm {\n    img {\n      width: $img-size-sm;\n      height: $img-size-sm;\n    }\n\n    .username,\n    .description,\n    .comment {\n      margin-left: 40px;\n    }\n\n    .username {\n      font-size: 14px;\n    }\n  }\n}\n\n// Image sizes\n.img-sm,\n.img-md,\n.img-lg {\n  float: left;\n}\n\n.img-sm {\n  height: $img-size-sm;\n  width: $img-size-sm;\n\n  + .img-push {\n    margin-left: $img-size-sm + $img-size-push;\n  }\n}\n\n.img-md {\n  width: $img-size-md;\n  height: $img-size-md;\n\n  + .img-push {\n    margin-left: $img-size-md + $img-size-push;\n  }\n}\n\n.img-lg {\n  width: $img-size-lg;\n  height: $img-size-lg;\n\n  + .img-push {\n    margin-left: $img-size-lg + $img-size-push;\n  }\n}\n\n// Image bordered\n.img-bordered {\n  border: 3px solid $gray-500;\n  padding: 3px;\n}\n\n.img-bordered-sm {\n  border: 2px solid $gray-500;\n  padding: 2px;\n}\n\n// Rounded and Circle Images\n.img-rounded {\n  @include border-radius($border-radius);\n}\n\n.img-circle {\n  @include border-radius(50%);\n}\n\n// Image sizes\n.img-size-64,\n.img-size-50,\n.img-size-32 {\n  height: auto;\n}\n\n.img-size-64 {\n  width: 64px;\n}\n\n.img-size-50 {\n  width: 50px;\n}\n\n.img-size-32 {\n  width: 32px;\n}\n\n// Block sizes\n.size-32,\n.size-40,\n.size-50 {\n  display: block;\n  text-align: center;\n}\n\n.size-32 {\n  height: 32px;\n  line-height: 32px;\n  width: 32px;\n}\n\n.size-40 {\n  height: 40px;\n  line-height: 40px;\n  width: 40px;\n}\n\n.size-50 {\n  height: 50px;\n  line-height: 50px;\n  width: 50px;\n}\n\n// General attachemnt block\n.attachment-block {\n  background-color: $gray-100;\n  border: 1px solid $card-border-color;\n  margin-bottom: 10px;\n  padding: 5px;\n\n  .attachment-img {\n    float: left;\n    height: auto;\n    max-height: 100px;\n    max-width: 100px;\n  }\n\n  .attachment-pushed {\n    margin-left: 110px;\n  }\n\n  .attachment-heading {\n    margin: 0;\n  }\n\n  .attachment-text {\n    color: $gray-700;\n  }\n}\n\n// Overlays for Card, InfoBox & SmallBox\n.card,\n.overlay-wrapper,\n.info-box,\n.small-box {\n  // Box overlay for LOADING STATE effect\n  > .overlay,\n  > .loading-img {\n    height: 100%;\n    left: 0;\n    position: absolute;\n    top: 0;\n    width: 100%;\n  }\n\n  .overlay {\n    @include border-radius($border-radius);\n    align-items: center;\n    background-color: rgba($white, .7);\n    display: flex;\n    justify-content: center;\n    z-index: 50;\n\n    > .fa,\n    > .fas,\n    > .far,\n    > .fab,\n    > .fal,\n    > .fad,\n    > .svg-inline--fa,\n    > .ion {\n      color: $gray-800;\n    }\n\n    &.dark {\n      background-color: rgba($black, .5);\n\n      > .fa,\n      > .fas,\n      > .far,\n      > .fab,\n      > .fal,\n      > .fad,\n      > .svg-inline--fa,\n      > .ion {\n        color: $gray-400;\n      }\n    }\n  }\n}\n\n.tab-pane {\n  // Box overlay for LOADING STATE effect on Tab Panels\n  > .overlay-wrapper {\n    position: relative;\n    > .overlay {\n      border-top-left-radius: 0;\n      border-top-right-radius: 0;\n      flex-direction: column;\n      margin-top: -$card-spacer-x;\n      margin-left: -$card-spacer-x;\n      height: calc(100% + 2 * #{$card-spacer-x});\n      width: calc(100% + 2 * #{$card-spacer-x});\n\n      &.dark {\n        color: $white;\n      }\n    }\n  }\n}\n\n// Ribbon\n.ribbon-wrapper {\n  height: $ribbon-wrapper-size;\n  overflow: hidden;\n  position: absolute;\n  right: -2px;\n  top: -2px;\n  width: $ribbon-wrapper-size;\n  z-index: 10;\n\n  &.ribbon-lg {\n    height: $ribbon-lg-wrapper-size;\n    width: $ribbon-lg-wrapper-size;\n\n    .ribbon {\n      right: $ribbon-lg-right;\n      top: $ribbon-lg-top;\n      width: $ribbon-lg-width;\n    }\n  }\n\n  &.ribbon-xl {\n    height: $ribbon-xl-wrapper-size;\n    width: $ribbon-xl-wrapper-size;\n\n    .ribbon {\n      right: $ribbon-xl-right;\n      top: $ribbon-xl-top;\n      width: $ribbon-xl-width;\n    }\n  }\n\n  .ribbon {\n    box-shadow: 0 0 $ribbon-border-size rgba($black, .3);\n    font-size: $ribbon-font-size;\n    line-height: $ribbon-line-height;\n    padding: $ribbon-padding;\n    position: relative;\n    right: $ribbon-right;\n    text-align: center;\n    text-shadow: 0 -1px 0 rgba($black, .4);\n    text-transform: uppercase;\n    top: $ribbon-top;\n    transform: rotate(45deg);\n    width: $ribbon-width;\n\n    &::before,\n    &::after {\n      border-left: $ribbon-border-size solid transparent;\n      border-right: $ribbon-border-size solid transparent;\n      border-top: $ribbon-border-size solid #9e9e9e;\n      bottom: -$ribbon-border-size;\n      content: \"\";\n      position: absolute;\n    }\n\n    &::before {\n      left: 0;\n    }\n\n    &::after {\n      right: 0;\n    }\n  }\n}\n\n// Scroll To Top\n.back-to-top {\n  bottom: 1.25rem;\n  position: fixed;\n  right: 1.25rem;\n  z-index: $zindex-control-sidebar + 1;\n\n  &:focus {\n    box-shadow: none;\n  }\n}\n\n// Pre\npre {\n  padding: .75rem;\n}\n\n// Blockquotes styles\nblockquote {\n  background-color: $white;\n  border-left: .7rem solid $primary;\n  margin: 1.5em .7rem;\n  padding: .5em .7rem;\n\n  .box & {\n    background-color: $gray-200;\n  }\n\n  p:last-child {\n    margin-bottom: 0;\n  }\n\n  h1,\n  h2,\n  h3,\n  h4,\n  h5,\n  h6 {\n    color: $primary;\n    font-size: 1.25rem;\n    font-weight: 600;\n  }\n\n  @each $color, $value in $theme-colors {\n    &.quote-#{$color} {\n      border-color: $value;\n\n      h1,\n      h2,\n      h3,\n      h4,\n      h5,\n      h6 {\n        color: $value;\n      }\n    }\n  }\n\n  @each $color, $value in $colors {\n    &.quote-#{$color} {\n      border-color: $value;\n\n      h1,\n      h2,\n      h3,\n      h4,\n      h5,\n      h6 {\n        color: $value;\n      }\n    }\n  }\n}\n\n\n// Tab Custom Content\n\n.tab-custom-content {\n  border-top: $nav-tabs-border-width solid $nav-tabs-border-color;\n  margin-top: .5rem;\n  padding-top: .5rem;\n}\n\n.nav + .tab-custom-content {\n  border-top: none;\n  border-bottom: $nav-tabs-border-width solid $nav-tabs-border-color;\n  margin-top: 0;\n  margin-bottom: .5rem;\n  padding-bottom: .5rem;\n}\n\n\n// Badge BTN Style\n.badge-btn {\n  border-radius: $button-border-radius-xs;\n  font-size: $button-font-size-xs;\n  font-weight: 400;\n  padding: $button-padding-y-xs * 2 $button-padding-x-xs * 2;\n}\n\n.badge-btn.badge-pill {\n  padding: .375rem .6rem;\n}\n\n@include dark-mode () {\n  a:not(.btn):hover {\n    color: lighten($link-color, 10%);\n  }\n  .attachment-block {\n    background-color: lighten($dark, 3.75%);\n\n    .attachment-text {\n      color: $gray-400;\n    }\n  }\n  blockquote {\n    background-color: lighten($dark, 5%);\n\n    @each $color, $value in $theme-colors {\n      &.quote-#{$color} {\n        border-color: $value;\n\n        h1,\n        h2,\n        h3,\n        h4,\n        h5,\n        h6 {\n          color: $value;\n        }\n      }\n    }\n\n    @each $color, $value in $colors {\n      &.quote-#{$color} {\n        border-color: $value;\n\n        h1,\n        h2,\n        h3,\n        h4,\n        h5,\n        h6 {\n          color: $value;\n        }\n      }\n    }\n  }\n  .close,\n  .mailbox-attachment-close {\n    color: $gray-500;\n    text-shadow: 0 1px 0 $gray-700;\n  }\n  .tab-custom-content {\n    border-color: $gray-600;\n  }\n  .list-group-item {\n    background-color: $dark;\n    border-color: $gray-600;\n  }\n}\n","//\n// Misc: Print\n//\n\n@media print {\n  //Add to elements that you do not want to show when printing\n  .no-print {\n    display: none !important;\n  }\n\n  //Elements that we want to hide when printing\n  .main-sidebar,\n  .main-header,\n  .content-header {\n    @extend .no-print;\n  }\n\n  //This is the only element that should appear, so let's remove the margins\n  .content-wrapper,\n  .main-footer {\n    @include translate(0, 0);\n    margin-left: 0 !important;\n    min-height: 0 !important;\n  }\n\n  .layout-fixed .content-wrapper {\n    padding-top: 0 !important;\n  }\n\n  //Invoice printing\n  .invoice {\n    border: 0;\n    margin: 0;\n    padding: 0;\n    width: 100%;\n  }\n\n  .invoice-col {\n    float: left;\n    width: 33.3333333%;\n  }\n\n  //Make sure table content displays properly\n  .table-responsive {\n    overflow: auto;\n\n    > .table tr th,\n    > .table tr td {\n      white-space: normal !important;\n    }\n  }\n}\n","//\n// Component: Text\n//\n\n// text modification\n.text-bold {\n  &,\n  &.table td,\n  &.table th {\n    font-weight: 700;\n  }\n}\n\n.text-xs {\n  font-size: $font-size-xs !important;\n}\n\n.text-sm {\n  font-size: $font-size-sm !important;\n}\n\n.text-md {\n  font-size: $font-size-base !important;\n}\n\n.text-lg {\n  font-size: $font-size-lg !important;\n}\n\n.text-xl {\n  font-size: $font-size-xl !important;\n}\n\n// text color variations\n@each $name, $color in $colors {\n  .text-#{$name} {\n    color: #{$color} !important;\n  }\n}\n\n@include dark-mode () {\n  .text-muted {\n    color: $gray-500 !important;\n  }\n\n  @each $name, $color in $colors-alt {\n    .text-#{$name} {\n      color: #{$color} !important;\n    }\n  }\n}\n","//\n// Component: Elevation\n//\n\n.elevation-0 {\n  box-shadow: none !important;\n}\n\n// Background colors (colors)\n@each $name, $value in $elevations {\n  .elevation-#{$name} {\n    box-shadow: $value !important;\n  }\n}\n","//\n// Mixins: Backgrounds\n//\n\n// Background Variant\n@mixin background-variant($name, $color) {\n  &.bg-#{$name} {\n    background-color: #{$color} !important;\n\n    &,\n    > a {\n      color: color-yiq($color) !important;\n    }\n\n    &.btn {\n      &:hover {\n        border-color: darken($color, 10%);\n        color: darken(color-yiq($color), 7.5%);\n      }\n\n      &:not(:disabled):not(.disabled):active,\n      &:not(:disabled):not(.disabled).active,\n      &:active,\n      &.active {\n        background-color: darken($color, 10%) !important;\n        border-color: darken($color, 12.5%);\n        color: color-yiq(darken($color, 10%));\n      }\n    }\n  }\n}\n\n// Background Gradient Variant\n@mixin background-gradient-variant($name, $color) {\n  .bg-gradient-#{$name} {\n    background: $color linear-gradient(180deg, mix($body-bg, $color, 15%), $color) repeat-x !important;\n    color: color-yiq($color);\n\n    &.btn {\n      &:not(:disabled):not(.disabled):active,\n      &:not(:disabled):not(.disabled).active,\n      .show > &.dropdown-toggle {\n        background-image: none !important;\n      }\n\n      &:hover {\n        background: $color linear-gradient(180deg, mix($body-bg, darken($color, 7.5%), 15%), darken($color, 7.5%)) repeat-x !important;\n        border-color: darken($color, 10%);\n        color: darken(color-yiq($color), 7.5%);\n      }\n\n      &:not(:disabled):not(.disabled):active,\n      &:not(:disabled):not(.disabled).active,\n      &:active,\n      &.active {\n        background: $color linear-gradient(180deg, mix($body-bg, darken($color, 10%), 15%), darken($color, 10%)) repeat-x !important;\n        border-color: darken($color, 12.5%);\n        color: color-yiq(darken($color, 10%));\n      }\n\n      &:disabled,\n      &.disabled {\n        background-image: none !important;\n        border-color: $color;\n        color: color-yiq($color);\n      }\n    }\n  }\n}\n","//\n// Misc: Colors\n//\n\n// Background colors (theme colors)\n@each $name, $color in $theme-colors {\n  @include background-variant($name, $color);\n}\n\n// Background colors (colors)\n@each $name, $color in $colors {\n  @include background-variant($name, $color);\n}\n\n@media print {\n  .table td,\n  .table th {\n    // Background colors (theme colors)\n    @each $name, $color in $theme-colors {\n      @include background-variant($name, $color);\n    }\n\n    // Background colors (colors)\n    @each $name, $color in $colors {\n      @include background-variant($name, $color);\n    }\n  }\n}\n\n.bg-gray {\n  background-color: $gray-500;\n  color: color-yiq($gray-500);\n}\n\n.bg-gray-light {\n  background-color: lighten($gray-200, 3%);\n  color: color-yiq(lighten($gray-200, 3%)) !important;\n}\n\n.bg-black {\n  background-color: $black;\n  color: color-yiq($black) !important;\n}\n\n.bg-white {\n  background-color: $white;\n  color: color-yiq($white) !important;\n}\n\n// Gradient Background colors (theme colors)\n@each $name, $color in $theme-colors {\n  @include background-gradient-variant($name, $color);\n}\n\n// Gradient Background colors (colors)\n@each $name, $color in $colors {\n  @include background-gradient-variant($name, $color);\n}\n\n// Backgrund Color Disabled\n[class^=\"bg-\"].disabled {\n  opacity: .65;\n}\n\n// Text muted hover\na.text-muted:hover {\n  color: theme-color(primary) !important;\n}\n\n// Link Styles\n.link-muted {\n  color: darken($gray-500, 30%);\n\n  &:hover,\n  &:focus {\n    color: darken($gray-500, 40%);\n  }\n}\n\n.link-black {\n  color: $gray-600;\n\n  &:hover,\n  &:focus {\n    color: lighten($gray-500, 20%);\n  }\n}\n\n// Accent colors (theme colors)\n@each $name, $color in $theme-colors {\n  @include accent-variant($name, $color);\n}\n\n// Accent colors (colors)\n@each $name, $color in $colors {\n  @include accent-variant($name, $color);\n}\n\n// Accent button override fix\n[class*=\"accent-\"] {\n  @each $name, $color in $theme-colors {\n    a.btn-#{$name} {\n      color: color-yiq($color);\n    }\n  }\n}\n\n@include dark-mode () {\n  .bg-light {\n    background-color: lighten($dark, 7.5%) !important;\n    color: $white !important;\n  }\n  .text-black,\n  .text-dark,\n  .link-black,\n  .link-dark {\n    color: $gray-400 !important;\n  }\n\n  // Background colors (theme colors)\n  @each $name, $color in $theme-colors-alt {\n    @include background-variant($name, $color);\n  }\n\n  // Background colors (colors)\n  @each $name, $color in $colors-alt {\n    @include background-variant($name, $color);\n  }\n\n  // Gradient Background colors (theme colors)\n  @each $name, $color in $theme-colors-alt {\n    @include background-gradient-variant($name, $color);\n  }\n\n  // Gradient Background colors (colors)\n  @each $name, $color in $colors-alt {\n    @include background-gradient-variant($name, $color);\n  }\n\n  // Accent colors (theme colors)\n  @each $name, $color in $theme-colors-alt {\n    @include accent-variant($name, $color);\n  }\n\n  [class*=\"accent-\"] {\n    @each $name, $color in $theme-colors-alt {\n      a.btn-#{$name} {\n        color: color-yiq($color);\n      }\n    }\n  }\n\n  // Accent colors (colors)\n  @each $name, $color in $colors-alt {\n    @include accent-variant($name, $color);\n  }\n\n  .border-dark {\n    border-color: lighten($dark, 10%) !important;\n  }\n}\n\n//\n","//\n// Mixins: Accent\n//\n\n// Accent Variant\n@mixin accent-variant($name, $color) {\n  $link-color: $color;\n  .accent-#{$name} {\n    $link-hover-color: darken($color, 15%);\n    $pagination-active-bg: $color;\n    $pagination-active-border-color: $color;\n\n    .btn-link,\n    a:not(.dropdown-item):not(.btn-app):not(.nav-link):not(.brand-link):not(.page-link):not(.badge):not(.btn),\n    .nav-tabs .nav-link {\n      color: $link-color;\n\n      @include hover () {\n        color: $link-hover-color;\n      }\n    }\n\n    .dropdown-item {\n      &:active,\n      &.active {\n        background-color: $color;\n        color: color-yiq($color);\n      }\n    }\n\n    .custom-control-input:checked ~ .custom-control-label {\n      &::before {\n        background-color: $color;\n        border-color: darken($color, 20%);\n      }\n\n      &::after {\n        $new-color: color-yiq($color);\n        background-image: str-replace($custom-checkbox-indicator-icon-checked, str-replace(#{$custom-control-indicator-checked-color}, \"#\", \"%23\"), str-replace(#{$new-color}, \"#\", \"%23\"));\n      }\n    }\n\n    .form-control:focus:not(.is-invalid):not(.is-warning):not(.is-valid),\n    .custom-select:focus,\n    .custom-control-input:focus:not(:checked) ~ .custom-control-label::before,\n    .custom-file-input:focus ~ .custom-file-label {\n      border-color: lighten($color, 25%);\n    }\n\n    .page-item {\n      .page-link {\n        color: $link-color;\n      }\n\n      &.active a,\n      &.active .page-link {\n        background-color: $pagination-active-bg;\n        border-color: $pagination-active-border-color;\n        color: $pagination-active-color;\n      }\n\n      &.disabled a,\n      &.disabled .page-link {\n        background-color: $pagination-disabled-bg;\n        border-color: $pagination-disabled-border-color;\n        color: $pagination-disabled-color;\n      }\n    }\n\n    [class*=\"sidebar-dark-\"] {\n      .sidebar {\n        a:not(.dropdown-item):not(.btn-app):not(.nav-link):not(.brand-link) {\n          color: $sidebar-dark-color;\n\n          @include hover () {\n            color: $sidebar-dark-hover-color;\n          }\n        }\n      }\n    }\n\n    [class*=\"sidebar-light-\"] {\n      .sidebar {\n        a:not(.dropdown-item):not(.btn-app):not(.nav-link):not(.brand-link) {\n          color: $sidebar-light-color;\n\n          @include hover () {\n            color: $sidebar-light-hover-color;\n          }\n        }\n      }\n    }\n  }\n  @include dark-mode () {\n    &.accent-#{$name} {\n      .page-item {\n        .page-link {\n          &:hover,\n          &:focus {\n            color: lighten($link-color, 5%);\n          }\n        }\n      }\n    }\n  }\n}\n"]}